		t.Fatal(err)
	}
	f.mu.Lock()
	after := f.channelWrites["GRU"] + f.channelWrites["SFO"] + f.channelWrites["FRA"]
	f.mu.Unlock()
	if before != after {
		t.Fatal("local tamper detected after publication")
	}
