	for index, arg := range producerArgs {
		if arg == "--signing-key" {
			producerArgs[index+1] = filepath.Join(inputs, "absent.key")
		}
		if arg == "--production-evidence-dir" {
			producerArgs[index+1] = t.TempDir()
		}
	}
