func (f *applyHTTPFixture) serve(w http.ResponseWriter, r *http.Request) {
	parts := strings.SplitN(r.URL.Path, "/", 7)
	if len(parts) != 7 || parts[1] != "n" || parts[3] != "b" || parts[5] != "o" || r.Header.Get("Authorization") == "" {
		http.Error(w, "invalid OCI request", http.StatusBadRequest)
		return
	}
	cell, _, _ := strings.Cut(strings.ToUpper(parts[4]), "-")
	name := parts[6]
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.objects[cell] == nil {
		f.objects[cell] = make(map[string][]byte)
	}
	if cell == "SFO" && f.failure == "unreachable" && name == releasechannel.StatusObject {
		f.mu.Unlock()
		<-r.Context().Done()
		f.mu.Lock()
		return
	}
	if cell == "SFO" && f.failure == "storage" && r.Method == http.MethodPut {
		http.Error(w, "unavailable", http.StatusForbidden)
		return
	}
	if r.Method == http.MethodPut {
		old, exists := f.objects[cell][name]
		if r.Header.Get("If-None-Match") == "*" && exists || r.Header.Get("If-Match") != "" && r.Header.Get("If-Match") != fmt.Sprintf("%x", len(old)) {
			w.WriteHeader(http.StatusPreconditionFailed)
			return
		}
		data, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		f.objects[cell][name] = data
		if name == releasechannel.ChannelObject {
			f.channelWrites[cell]++
		} else {
			f.binaryCreates[cell]++
		}
		w.Header().Set("etag", fmt.Sprintf("%x", len(data)))
		return
	}
	data, exists := f.objects[cell][name]
	if name == releasechannel.StatusObject {
		status := releasechannel.Status{Schema: releasechannel.StatusSchema, Cell: cell, Environment: "production",
			Architectures: []string{"amd64"}, UpdatedAt: time.Now().UTC()}
		if cell == "SFO" {
			switch f.failure {
			case "missing":
				w.WriteHeader(http.StatusNotFound)
				return
			case "stale":
				status.UpdatedAt = status.UpdatedAt.Add(-time.Hour)
			case "environment":
				status.Environment = "canary"
			case "architecture":
				status.Architectures = []string{"arm64"}
			}
		}
		if wire, ok := f.objects[cell][releasechannel.ChannelObject]; ok {
			var channel releasechannel.Channel
			if err := json.Unmarshal(wire, &channel); err == nil {
				_, err := channel.Verify(f.roots, cell, "production", time.Now().UTC())
				status.SourceRevision, status.RunNumber = channel.SourceRevision, channel.RunNumber
				status.State = releasechannel.StateComplete
				if err != nil {
					status.State, status.Reason = releasechannel.StateFailed, err.Error()
				}
			}
		}
		data, _ = json.Marshal(status)
		exists = true
	}
	if !exists {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	w.Header().Set("etag", fmt.Sprintf("%x", len(data)))
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(data)
}

func applyFixtureCommand(t *testing.T, dir, program string, args ...string) string {
	t.Helper()
	name := program
	if os.Getenv("CI") != "true" {
		name, args = "nice", append([]string{"-n", "19", program}, args...)
	}
	command := exec.CommandContext(t.Context(), name, args...)
	command.Dir = dir
	command.Env = append(os.Environ(), "CGO_ENABLED=0", "GOOS=linux", "GOARCH=amd64")
	output, err := command.CombinedOutput()
	if err != nil {
		t.Fatalf("%s: %v\n%s", program, err, output)
	}
	return string(output)
}

type applyFixtureLineage struct {
	t   *testing.T
	dir string
}

func (l applyFixtureLineage) CheckLineage(base, revision, ref string) error {
	applyFixtureCommand(l.t, l.dir, "git", "merge-base", "--is-ancestor", base, revision)
	applyFixtureCommand(l.t, l.dir, "git", "merge-base", "--is-ancestor", revision, ref)
	return nil
}

// OCI SDK endpoint selection runs per operation; force all fixture traffic local.
type applyHTTPDispatcher struct{ server *httptest.Server }

func (d applyHTTPDispatcher) Do(request *http.Request) (*http.Response, error) {
	local, err := url.Parse(d.server.URL)
	if err != nil {
		return nil, err
	}
	request = request.Clone(request.Context())
	request.URL = request.URL.Clone()
	request.URL.Scheme, request.URL.Host = local.Scheme, local.Host
	request.Host = local.Host
	return d.server.Client().Do(request)
}

func (c command) applyWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("apply", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	directory := flags.String("dir", "", "signed bundle: CELL/channel.json and binaries/SHA256")
	rootPath := flags.String("root-key", "", "existing trusted root public key PEM, outside the bundle")
	namespace := flags.String("namespace", "", "Object Storage namespace of the regional head buckets")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *directory == "" || *rootPath == "" || !validStorageToken(*namespace) || flags.NArg() != 0 {
		return errors.New("apply requires --dir, --root-key and --namespace")
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(*directory)
	if err != nil {
		return err
	}
	var cells []string
	for _, entry := range entries {
		if entry.IsDir() && validRegion(entry.Name()) {
			cells = append(cells, entry.Name())
		}
	}
	cells, err = deploymentCells(c.ctx, cells, nil)
	if err != nil {
		return err
	}
	budget := rollout.ObservationBudget
	if env.timeout > 0 {
		budget = min(budget, env.timeout)
	}
	type target struct {
		channel  releasechannel.Channel
		binaries map[string]binaryReceipt
	}
	targets := make([]target, 0, len(cells))
	var revision string
	var sequence int64
	inspected := make(map[string]binaryReceipt)
	// Verify the whole bundle before writing any region's objects or channel.
	for _, cell := range cells {
		data, err := readBoundedRegular(filepath.Join(*directory, cell, "channel.json"), releasechannel.MaxChannelBytes)
		if err != nil {
			return err
		}
		var channel releasechannel.Channel
		if err := protocol.DecodeStrict(data, &channel, releasechannel.MaxChannelBytes); err != nil {
			return err
		}
		verified, err := channel.Verify(roots, cell, channel.Environment, time.Now().UTC())
		if err != nil {
			return fmt.Errorf("%s signed channel: %w", cell, err)
		}
		if revision == "" {
			revision, sequence = channel.SourceRevision, channel.RunNumber
		}
		if channel.SourceRevision != revision || channel.RunNumber != sequence {
			return errors.New("bundle mixes source revisions or release sequences")
		}
		binaries := make(map[string]binaryReceipt, len(verified))
		for architecture, proof := range verified {
			receipt := proof.Receipt()
			observed, found := inspected[receipt.SHA256]
			if !found {
				var err error
				observed, err = env.inspect(filepath.Join(*directory, "binaries", receipt.SHA256), receipt.GoVersion, revision)
				if err != nil {
					return err
				}
				inspected[receipt.SHA256] = observed
			}
			observed.QualificationSHA256 = receipt.QualificationSHA256
			if observed != receipt {
				return fmt.Errorf("%s %s bytes or build metadata differ from signed receipt", cell, architecture)
			}
			binaries[architecture] = receipt
		}
		targets = append(targets, target{channel, binaries})
	}
	progress := &deploymentWriter{Writer: c.output}
	failures := make([]error, len(targets))
	var regions errgroup.Group
	regions.SetLimit(4)
	for index, target := range targets {
		regions.Go(func() error {
			deadline := time.Now().UTC().Add(budget)
			ctx, cancel := context.WithDeadline(c.ctx, deadline)
			defer cancel()
			regional := c
			regional.ctx = ctx
			apply := func() error {
				if err := regional.verifyProductionArtifacts(filepath.Join(*directory, "production"), roots, target.channel.Cell, target.channel.Environment, target.binaries, deadline); err != nil {
					return err
				}
				location, err := channelLocation(env, target.channel.Cell, *namespace)
				if err != nil {
					return err
				}
				scope, err := deploymentScope(ctx, location, target.channel.Cell)
				if err != nil {
					return err
				}
				if _, err := target.channel.Verify(roots, target.channel.Cell, scope.Environment, deadline); err != nil {
					return fmt.Errorf("signed channel must remain valid through rollout: %w", err)
				}
				if len(target.binaries) != len(scope.Architectures) {
					return errors.New("bundle architectures differ from regional scope")
				}
				for _, architecture := range scope.Architectures {
					if _, found := target.binaries[architecture]; !found {
						return fmt.Errorf("bundle lacks %s", architecture)
					}
				}
				for _, receipt := range target.binaries {
					if err := regional.uploadBinary(location, filepath.Join(*directory, "binaries", receipt.SHA256), receipt.SHA256); err != nil {
						return err
					}
				}
				if err := releasechannel.Publish(ctx, location, target.channel); err != nil {
					return err
				}
				fmt.Fprintf(progress, "%s published signed release %d %s\n", target.channel.Cell, sequence, revision)
				return releasechannel.Await(ctx, location, target.channel, 5*time.Second, deadline, progress)
			}
			if err := apply(); err != nil {
				failures[index] = fmt.Errorf("%s: %w", target.channel.Cell, err)
				fmt.Fprintf(progress, "%s failed: %v\n", target.channel.Cell, err)
			}
			return nil
		})
	}
	_ = regions.Wait()
	return errors.Join(failures...)
}

func (channel Channel) Verify(roots trust.Keyring, cell, environment string, now time.Time) (map[string]release.VerifiedBinary, error) {
	if channel.Schema != ChannelSchema || channel.Cell != cell || channel.Environment != environment ||
		!release.ValidSourceRevision(channel.SourceRevision) || channel.RunNumber <= 0 ||
		len(channel.Receipts) == 0 || len(channel.Receipts) > 2 {
		return nil, fmt.Errorf("%w: channel scope", ErrInvalid)
	}
	var migrationDigest, sequenceSigner string
	if channel.ReleaseSequence > 0 {
		envelope, err := trust.DecodeEnvelope(channel.SequenceMigration)
		if err != nil {
			return nil, err
		}
		migration, err := release.VerifySequenceMigrationHistorical(envelope, roots, "orchestrator", environment)
		if err != nil {
			return nil, err
		}
		if channel.ReleaseSequence <= migration.SequenceFloor {
			return nil, fmt.Errorf("%w: release sequence does not exceed migration floor", ErrInvalid)
		}
		sequenceSigner = migration.SignerKeyID
		migrationDigest, err = trust.Fingerprint(envelope)
		if err != nil {
			return nil, err
		}
	} else if len(channel.SequenceMigration) > 0 {
		return nil, fmt.Errorf("%w: legacy channel carries sequence migration", ErrInvalid)
	}
	verified := make(map[string]release.VerifiedBinary, len(channel.Receipts))
	for _, wire := range channel.Receipts {
		envelope, err := trust.DecodeEnvelope(wire)
		if err != nil {
			return nil, err
		}
		if channel.ReleaseSequence > 0 && envelope.KeyID != sequenceSigner {
			return nil, fmt.Errorf("%w: receipt signer does not own release order", ErrInvalid)
		}
		architecture, _ := strings.CutPrefix(envelope.Scope.Slot, "linux-")
		if _, seen := verified[architecture]; seen {
			return nil, fmt.Errorf("%w: two receipts for %s", ErrInvalid, architecture)
		}
		binary, err := release.VerifyQualifiedBinaryUpdateCurrent(wire, channel.Delegation, roots,
			release.UpdateExpectation{Environment: environment, Cell: cell, Architecture: architecture}, now)
		if err != nil {
			return nil, err
		}
		// The payload is authentic now; its lineage carries the signed run.
		var receipt release.BinaryUpdateReceipt
		if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
			return nil, err
		}
		if binary.Receipt().SourceRevision != channel.SourceRevision || receipt.Lineage.QualificationRunNum != channel.RunNumber || receipt.ReleaseSequence != channel.ReleaseSequence || receipt.SequenceMigrationSHA256 != migrationDigest {
			return nil, fmt.Errorf("%w: receipt for %s names another release", ErrInvalid, architecture)
		}
		verified[architecture] = binary
	}
	return verified, nil
}

func Publish(ctx context.Context, location Location, channel Channel) error {
	wire, err := json.Marshal(channel, json.Deterministic(true))
	if err != nil {
		return err
	}
	for range 3 {
		current, etag, found, err := location.get(ctx, ChannelObject, MaxChannelBytes)
		if err != nil {
			return err
		}
		if found {
			var existing Channel
			if err := json.Unmarshal(current, &existing); err != nil {
				return fmt.Errorf("decode the current release channel: %w", err)
			}
			if err := compareChannelOrder(existing, channel); err != nil {
				return err
			}
		}
		if err := location.put(ctx, ChannelObject, wire, etag); !errors.Is(err, ErrConflict) {
			return err
		}
	}
	return ErrConflict
}

// ReadChannel returns the region's channel; found is false when it has none.
func ReadChannel(ctx context.Context, location Location) (Channel, bool, error) {
	var channel Channel
	found, err := location.read(ctx, ChannelObject, MaxChannelBytes, &channel)
	return channel, found, err
}

// ReadStatus returns the region's status; found is false when it has none.
// Unknown fields are ignored: a region may run an older or newer binary.
func ReadStatus(ctx context.Context, location Location) (Status, bool, error) {
	var status Status
	found, err := location.read(ctx, StatusObject, maxStatusBytes, &status)
	return status, found, err
}

func Await(ctx context.Context, location Location, channel Channel, poll time.Duration, deadline time.Time,
	progress io.Writer,
) error {
	var last string
	for {
		status, found, err := ReadStatus(ctx, location)
		line := "waiting for the region to report"
		switch {
		case err != nil:
			line = "status read failed: " + err.Error()
		case !found || channel.ReleaseSequence > 0 && status.ReleaseSequence < channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.ReleaseSequence == 0 && status.RunNumber < channel.RunNumber:
		case status.ReleaseSequence > channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.RunNumber > channel.RunNumber:
			return fmt.Errorf("%w: %s moved on to run %d", ErrFailed, channel.Cell, status.RunNumber)
		case status.Cell != channel.Cell || status.SourceRevision != channel.SourceRevision:
			return fmt.Errorf("%w: %s reports run %d for %s %s", ErrFailed, channel.Cell, status.RunNumber,
				Clip(status.Cell), Clip(status.SourceRevision))
		case status.State == StateComplete:
			fmt.Fprintf(progress, "%s complete: run %d %s\n", channel.Cell, channel.RunNumber, channel.SourceRevision)
			return nil
		case status.State == StateFailed:
			return fmt.Errorf("%w: %s rolled back run %d: %s", ErrFailed, channel.Cell, channel.RunNumber, Clip(status.Reason))
		default:
			line = Clip(string(status.State) + " " + status.Reason)
		}
		if line != last {
			fmt.Fprintf(progress, "%s %s\n", channel.Cell, line)
			last = line
		}
		if !time.Now().Before(deadline) {
			return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
		}
		select {
		case <-ctx.Done():
			if !time.Now().Before(deadline) {
				return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
			}
			return ctx.Err()
		case <-time.After(min(poll, time.Until(deadline))):
		}
	}
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

// put writes data only if the object still has etag, or does not exist when
// etag is empty.
func (location Location) put(ctx context.Context, name string, data []byte, etag string) error {
	request := objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(data))), PutObjectBody: io.NopCloser(bytes.NewReader(data)),
		ContentType: new("application/json"),
	}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err := location.Client.PutObject(ctx, request)
	if httpStatus(err) == http.StatusPreconditionFailed {
		return ErrConflict
	}
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

func writeProductionEvidence(t *testing.T, directory string, candidate release.ProductionExpectation) release.ProductionQualification {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(directory, "objects"), 0o700); err != nil {
		t.Fatal(err)
	}
	record := release.ProductionQualification{Schema: release.ProductionQualificationSchema, Candidate: candidate}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		data, err := json.Marshal(struct{ Gate, SourceRevision, ArtifactSHA256 string }{gate, candidate.SourceRevision, candidate.ArtifactSHA256})
		if err != nil {
			t.Fatal(err)
		}
		digest := sha256.Sum256(data)
		sum := hex.EncodeToString(digest[:])
		if err := os.WriteFile(filepath.Join(directory, "objects", sum), data, 0o600); err != nil {
			t.Fatal(err)
		}
		record.Evidence = append(record.Evidence, release.ProductionGateEvidence{Gate: gate, SHA256: sum,
			Bytes: int64(len(data)), CompletedAt: time.Now().UTC().Add(-3 * time.Hour)})
	}
	return record
}

func writeProductionRecord(t *testing.T, path string, record release.ProductionQualification, private ed25519.PrivateKey, issued, expires time.Time) {
	t.Helper()
	payload, err := trust.EncodePayload(record)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := trust.Sign(payload, release.ProductionQualificationScope(record.Candidate), issued, expires, private)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, wire, 0o600); err != nil {
		t.Fatal(err)
	}
}

func (c command) verifyProductionArtifacts(evidenceDir string, roots trust.Keyring, cell, environment string, binaries map[string]binaryReceipt, now time.Time) error {
	if len(binaries) == 0 {
		return fmt.Errorf("%w: no candidate artifacts", release.ErrProductionQualification)
	}
	for architecture, binary := range binaries {
		if err := binary.Validate(); err != nil {
			return fmt.Errorf("%w: %w", release.ErrProductionQualification, err)
		}
		if binary.GOARCH != architecture {
			return fmt.Errorf("%w: artifact architecture", release.ErrProductionQualification)
		}
		expected := release.ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
			QualificationSHA256: binary.QualificationSHA256, Cell: cell, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: architecture, Role: "orchestrator"}
		if err := c.verifyProductionCandidate(evidenceDir, roots, expected, now); err != nil {
			return err
		}
	}
	return c.ctx.Err()
}

// verifyProductionCandidate consumes only signed qualification and retained bytes.
func (c command) verifyProductionCandidate(evidenceDir string, roots trust.Keyring, expected release.ProductionExpectation, now time.Time) error {
	directory := filepath.Join(evidenceDir, expected.Cell, expected.Architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return fmt.Errorf("%w: %s %s record: %w", release.ErrProductionQualification, expected.Cell, expected.Architecture, err)
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("%w: qualification delegation: %w", release.ErrProductionQualification, err)
	}
	if _, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, time.Now().UTC()); err != nil {
		return fmt.Errorf("%s %s current admission: %w", expected.Cell, expected.Architecture, err)
	}
	qualification, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, now)
	if err != nil {
		return fmt.Errorf("%s %s: %w", expected.Cell, expected.Architecture, err)
	}
	for _, evidence := range qualification.Evidence {
		file, err := openRegular(filepath.Join(evidenceDir, "objects", evidence.SHA256))
		if err != nil {
			return fmt.Errorf("%w: %s %s evidence: %w", release.ErrProductionQualification, expected.Cell, evidence.Gate, err)
		}
		if err := errors.Join(release.VerifyProductionEvidence(c.ctx, file, evidence, expected), file.Close()); err != nil {
			return fmt.Errorf("%s %s retained evidence: %w", expected.Cell, evidence.Gate, err)
		}
	}
	return c.ctx.Err()
}

func readProductionProof(evidenceDir, cell, architecture string) (release.ProductionProof, error) {
	directory := filepath.Join(evidenceDir, cell, architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return release.ProductionProof{}, err
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return release.ProductionProof{}, err
	}
	return release.ProductionProof{Qualification: wire, Delegation: delegation}, nil
}

func productionBinaryExpectation(binary BinaryReceipt, expected UpdateExpectation) ProductionExpectation {
	return ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
		QualificationSHA256: binary.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment,
		Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: "orchestrator"}
}

// VerifyQualifiedBinaryUpdateCurrent requires both release and qualification
// authority at the consumer's current time and own target scope.
func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

// AttachProductionQualification preserves source/run provenance and signs the
// independent authority's exact candidate proof into the update receipt.
func AttachProductionQualification(envelope trust.Envelope, proof ProductionProof, delegationWire []byte, roots trust.Keyring, private ed25519.PrivateKey, expected UpdateExpectation, now time.Time) (trust.Envelope, error) {
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyProductionCurrent(proof.Qualification, proof.Delegation, roots, productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return trust.Envelope{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return trust.Envelope{}, err
	}
	receipt.Production = &proof
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	signed, err := trust.Sign(payload, envelope.Scope, envelope.IssuedAt, envelope.ExpiresAt, private)
	if err != nil {
		return trust.Envelope{}, err
	}
	wire, err = trust.EncodeEnvelope(signed)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire, roots, expected, now); err != nil {
		return trust.Envelope{}, err
	}
	return signed, nil
}

func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

func VerifyProductionEvidence(ctx context.Context, reader io.Reader, evidence ProductionGateEvidence, expected ProductionExpectation) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if reader == nil || evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || !digestPattern.MatchString(evidence.SHA256) {
		return fmt.Errorf("%w: retained %s evidence metadata", ErrProductionQualification, evidence.Gate)
	}
	digest := sha256.New()
	var body bytes.Buffer
	var destination io.Writer = digest
	if evidence.Gate == RootCredentialBoundaryGate {
		destination = io.MultiWriter(digest, &body)
	}
	count, err := io.Copy(destination, io.LimitReader(reader, evidence.Bytes+1))
	if err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if count != evidence.Bytes || hex.EncodeToString(digest.Sum(nil)) != evidence.SHA256 {
		return fmt.Errorf("%w: retained %s evidence differs from the signed size or SHA-256", ErrProductionQualification, evidence.Gate)
	}
	if evidence.Gate == RootCredentialBoundaryGate {
		var boundary RootCredentialBoundaryEvidence
		if err := protocol.DecodeStrict(body.Bytes(), &boundary, MaxProductionEvidenceBytes); err != nil {
			return fmt.Errorf("%w: root credential boundary evidence: %w", ErrProductionQualification, err)
		}
		if err := boundary.Validate(expected); err != nil {
			return err
		}
		if !boundary.CompletedAt.Equal(evidence.CompletedAt) {
			return fmt.Errorf("%w: root credential boundary completion time", ErrProductionQualification)
		}
	}
	return ctx.Err()
}

func (c command) inspectBinary(path, requiredGoVersion, expectedRevision string) (binaryReceipt, error) {
	if err := c.ctx.Err(); err != nil {
		return binaryReceipt{}, err
	}
	if !release.ValidSourceRevision(expectedRevision) || requiredGoVersion == "" {
		return binaryReceipt{}, errors.New("binary candidate requires a lowercase 40-character source revision and Go version")
	}
	file, err := openRegular(path)
	if err != nil {
		return binaryReceipt{}, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return binaryReceipt{}, err
	}
	if info.Size() <= 0 || info.Size() > maxArtifactBytes {
		return binaryReceipt{}, errors.New("binary is empty or exceeds the static artifact size limit")
	}
	elfFile, err := elf.NewFile(file)
	if err != nil {
		return binaryReceipt{}, fmt.Errorf("parse binary ELF: %w", err)
	}
	defer elfFile.Close()
	if elfFile.Class != elf.ELFCLASS64 || elfFile.Data != elf.ELFDATA2LSB || elfFile.Type != elf.ET_EXEC && elfFile.Type != elf.ET_DYN {
		return binaryReceipt{}, errors.New("binary must be a 64-bit little-endian Linux executable")
	}
	goarch, machine, err := elfArchitecture(elfFile.Machine)
	if err != nil {
		return binaryReceipt{}, err
	}
	for _, program := range elfFile.Progs {
		if program.Type == elf.PT_INTERP {
			return binaryReceipt{}, errors.New("binary has a dynamic interpreter")
		}
	}
	if needed, err := elfFile.DynString(elf.DT_NEEDED); err == nil && len(needed) != 0 {
		return binaryReceipt{}, errors.New("binary has dynamic library dependencies")
	}
	build, err := buildinfo.ReadFile(path)
	if err != nil {
		return binaryReceipt{}, fmt.Errorf("read Go build metadata: %w", err)
	}
	settings := make(map[string]string, len(build.Settings))
	for _, setting := range build.Settings {
		settings[setting.Key] = setting.Value
	}
	if build.GoVersion != requiredGoVersion || settings["GOOS"] != "linux" || settings["vcs.revision"] != expectedRevision || settings["vcs.modified"] != "false" {
		return binaryReceipt{}, fmt.Errorf("binary build metadata must match go=%s revision=%s with vcs.modified=false", requiredGoVersion, expectedRevision)
	}
	if settings["GOARCH"] != goarch {
		return binaryReceipt{}, errors.New("ELF architecture does not match Go build metadata")
	}
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		return binaryReceipt{}, err
	}
	digest, _, err := c.hashArtifact(file)
	if err != nil {
		return binaryReceipt{}, err
	}
	return binaryReceipt{
		Schema: binarySchema, SourceRevision: expectedRevision, GoVersion: build.GoVersion,
		GOOS: settings["GOOS"], GOARCH: settings["GOARCH"], ELFMachine: machine, Static: true,
		Bytes: info.Size(), SHA256: hex.EncodeToString(digest),
	}, nil
}

func binaryPath(directory, architecture string) string {
	return filepath.Join(directory, "terrascale-orchestrator-linux-"+architecture)
}

// uploadBinary stores the binary under its digest unless the bucket already
// holds exactly those bytes.
func (c command) uploadBinary(location releasechannel.Location, path, sha256 string) error {
	file, size, digest, err := c.openHashedArtifact(path, maxArtifactBytes)
	if err != nil {
		return err
	}
	defer file.Close()
	if hex.EncodeToString(digest) != sha256 {
		return errors.New("binary changed after it was inspected")
	}
	return putImmutable(c.ctx, location.Client, location.Namespace, location.Bucket,
		releasechannel.BinaryObject(sha256), file, size, digest)
}

func channelLocation(env deployEnv, cell, namespace string) (releasechannel.Location, error) {
	bucket, err := releasechannel.BucketName(cell)
	if err != nil {
		return releasechannel.Location{}, err
	}
	client, err := env.storage(cell)
	if err != nil {
		return releasechannel.Location{}, err
	}
	return releasechannel.Location{Client: client, Namespace: namespace, Bucket: bucket}, nil
}

func putImmutable(ctx context.Context, client immutableObjectClient, namespace, bucket, name string, source io.ReadSeeker, size int64, digest []byte) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if size <= 0 || size > maxArtifactBytes || len(digest) != sha256.Size {
		return errors.New("immutable object size or SHA-256 digest is invalid")
	}
	if _, err := source.Seek(0, io.SeekStart); err != nil {
		return fmt.Errorf("rewind release asset: %w", err)
	}
	noOverwrite := "*"
	contentType := "application/octet-stream"
	cacheControl := "public, max-age=31536000, immutable"
	checksum := base64.StdEncoding.EncodeToString(digest)
	if err := ctx.Err(); err != nil {
		return err
	}
	_, putErr := client.PutObject(ctx, objectstorage.PutObjectRequest{
		NamespaceName: common.String(namespace), BucketName: common.String(bucket), ObjectName: common.String(name),
		ContentLength: common.Int64(size), PutObjectBody: io.NopCloser(&boundedReadSeeker{source: source, size: size}),
		IfNoneMatch: common.String(noOverwrite), ContentType: common.String(contentType), CacheControl: common.String(cacheControl),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256, OpcContentSha256: common.String(checksum),
	})
	getErr := getExactObjectDigest(ctx, client, namespace, bucket, name, size, digest)
	if getErr != nil {
		if putErr != nil {
			return errors.Join(fmt.Errorf("create immutable release object: %w", putErr), fmt.Errorf("read back release object: %w", getErr))
		}
		return fmt.Errorf("release object upload succeeded but exact read-back failed: %w", getErr)
	}
	if putErr != nil {
		// Conditional create may lose an acknowledgement or find an identical
		// earlier publication. Exact read-back proves this immutable receipt.
		return nil
	}
	return nil
}

func getExactObjectDigest(ctx context.Context, client immutableObjectClient, namespace, bucket, name string, expectedBytes int64, expectedDigest []byte) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	response, err := ociclient.ReadObject(ctx, client, objectstorage.GetObjectRequest{
		NamespaceName: common.String(namespace), BucketName: common.String(bucket), ObjectName: common.String(name),
	})
	if err != nil {
		return err
	}
	defer response.Content.Close()
	if response.ContentLength != nil && *response.ContentLength != expectedBytes {
		return fmt.Errorf("stored object length %d does not match %d", *response.ContentLength, expectedBytes)
	}
	hash := sha256.New()
	read, err := io.Copy(hash, commandio.Reader(ctx, io.LimitReader(response.Content, expectedBytes+1)))
	if err != nil {
		return err
	}
	if read != expectedBytes {
		return fmt.Errorf("stored object read %d bytes, expected %d", read, expectedBytes)
	}
	if !bytes.Equal(hash.Sum(nil), expectedDigest) {
		return errors.New("release object name already contains different bytes; refusing overwrite")
	}
	return nil
}

type delegationFixture struct {
	now         time.Time
	rootPublic  ed25519.PublicKey
	leafPrivate ed25519.PrivateKey
	rootPath    string
	privatePath string
	leafPath    string
	directory   string
}

func newDelegationFixture(t *testing.T) delegationFixture {
	t.Helper()
	rootPublic, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leafPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	directory := t.TempDir()
	fixture := delegationFixture{now: time.Now().UTC().Truncate(time.Second), rootPublic: rootPublic,
		leafPrivate: leafPrivate, rootPath: filepath.Join(directory, "root.pub"),
		privatePath: filepath.Join(directory, "root.key"), leafPath: filepath.Join(directory, "leaf.pub"),
		directory: directory}
	writePublicKey(t, fixture.rootPath, rootPublic)
	writePublicKey(t, fixture.leafPath, leafPublic)
	writePrivateKey(t, fixture.privatePath, rootPrivate)
	return fixture
}

func writePublicKey(t *testing.T, path string, public ed25519.PublicKey) {
	t.Helper()
	der, err := x509.MarshalPKIXPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	writeFixtureFile(t, path, pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der}), 0o600)
}

func writePrivateKey(t *testing.T, path string, private ed25519.PrivateKey) {
	t.Helper()
	der, err := x509.MarshalPKCS8PrivateKey(private)
	if err != nil {
		t.Fatal(err)
	}
	writeFixtureFile(t, path, pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der}), 0o600)
}

func (fixture delegationFixture) args(output string) []string {
	return []string{"--subject-public-key", fixture.leafPath, "--root-key", fixture.rootPath,
		"--signing-key", fixture.privatePath, "--source-revision", testRevision,
		"--arch", "amd64", "--arch", "arm64",
		"--issued-at", fixture.now.Add(-time.Minute).Format(time.RFC3339),
		"--expires-at", fixture.now.Add(time.Hour).Format(time.RFC3339), "--out", output}
}

