func signDelegationAt(args []string, now time.Time) error {
	return (command{ctx: context.Background(), output: os.Stdout}).signDelegationAt(args, now)
}

func (architectures *releaseArchitectures) String() string {
	return fmt.Sprint([]string(*architectures))
}

func (architectures *releaseArchitectures) Set(value string) error {
	if value != "amd64" && value != "arm64" {
		return errors.New("architecture must be amd64 or arm64")
	}
	for _, existing := range *architectures {
		if existing == value {
			return errors.New("duplicate architecture")
		}
	}
	*architectures = append(*architectures, value)
	return nil
}

func (c command) signDelegation(args []string) error {
	return c.signDelegationAt(args, time.Now().UTC())
}

func (c command) signDelegationAt(args []string, now time.Time) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	flags := flag.NewFlagSet("sign-delegation", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	leafPath := flags.String("subject-public-key", "", "delegated Ed25519 PKIX public key PEM")
	rootPath := flags.String("root-key", "", "offline root Ed25519 PKIX public key PEM")
	privatePath := flags.String("signing-key", "", "owner-only offline root Ed25519 PKCS#8 private key PEM")
	sourceRevision := flags.String("source-revision", "", "exact 40-character source revision")
	var architectures releaseArchitectures
	flags.Var(&architectures, "arch", "exact release architecture: amd64 or arm64; repeatable")
	imageRegion := flags.String("image-cell", "", "catalog cell of the image, e.g. GRU")
	imageOCID := flags.String("image-ocid", "", "exact OCI image OCID imported into the cell's region")
	previousPath := flags.String("previous-delegation", "", "current binary-only delegation to extend for an image")
	environment := flags.String("environment", "canary", "release environment; canary only")
	issuedAtText := flags.String("issued-at", "", "canonical UTC RFC3339 issuance instant")
	expiresAtText := flags.String("expires-at", "", "canonical UTC RFC3339 expiry instant")
	output := flags.String("out", "", "new root-signed delegation envelope")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *leafPath == "" || *rootPath == "" || *privatePath == "" || *output == "" ||
		!release.ValidSourceRevision(*sourceRevision) || len(architectures) == 0 ||
		*environment != "canary" || flags.NArg() != 0 ||
		((*imageRegion == "") != (*imageOCID == "")) ||
		((*imageOCID == "") != (*previousPath == "")) ||
		(*imageRegion != "" && !release.ValidOCIImageIDForRegion(*imageOCID, *imageRegion)) {
		return errors.New("sign-delegation requires exact canary source, architecture, keys, UTC interval, output, and optional catalog-cell image pair")
	}
	issuedAt, err := parseDelegationUTC(*issuedAtText)
	if err != nil {
		return fmt.Errorf("issued-at: %w", err)
	}
	expiresAt, err := parseDelegationUTC(*expiresAtText)
	if err != nil {
		return fmt.Errorf("expires-at: %w", err)
	}
	if now.IsZero() || issuedAt.After(now) || !expiresAt.After(now) ||
		!expiresAt.After(issuedAt) || expiresAt.Sub(issuedAt) > release.MaxDelegationLifetime {
		return errors.New("delegation must be current and valid for no more than the release lifetime")
	}
	leafPublic, err := readLeafPublicKey(*leafPath)
	if err != nil {
		return err
	}
	rootPublic, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	if bytes.Equal(leafPublic, rootPublic) {
		return errors.New("delegated leaf must differ from offline root")
	}
	rootPrivate, err := readOfflineRootPrivateKey(*privatePath)
	if err != nil {
		return err
	}
	defer clear(rootPrivate)
	if !bytes.Equal(rootPrivate.Public().(ed25519.PublicKey), rootPublic) {
		return errors.New("offline root signing key does not match root public key")
	}
	rootKeys, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		return err
	}
	leafID, err := trust.KeyID(leafPublic)
	if err != nil {
		return err
	}
	leafEncoded, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		return err
	}
	binaryCapabilities := make([]trust.Capability, 0, len(architectures))
	for _, architecture := range architectures {
		scope := release.BinaryScope(release.BinaryReceipt{SourceRevision: *sourceRevision, GOARCH: architecture}, "canary")
		binaryCapabilities = append(binaryCapabilities, capabilityForScope(scope))
	}
	capabilities := binaryCapabilities
	if *imageOCID != "" {
		previousEnvelope, err := readEnvelope(*previousPath)
		if err != nil {
			return fmt.Errorf("read previous binary delegation: %w", err)
		}
		previous, err := trust.VerifyDelegationCurrent(previousEnvelope, rootKeys, now,
			trust.Policy{MaxLifetime: release.MaxDelegationLifetime, ClockSkew: time.Minute})
		if err != nil {
			return fmt.Errorf("verify current previous binary delegation: %w", err)
		}
		if previous.SubjectKeyID() != leafID || !previousEnvelope.IssuedAt.Equal(issuedAt) ||
			!previousEnvelope.ExpiresAt.Equal(expiresAt) ||
			!sameCapabilitySet(previous.Capabilities(), binaryCapabilities) {
			return errors.New("image phase differs from previous leaf, source, architecture set, or validity interval")
		}
		capabilities = previous.Capabilities()
		scope := release.ImageScope(release.ImageReceipt{SourceRevision: *sourceRevision,
			OCIRegion: *imageRegion, OCIImageOCID: *imageOCID}, "canary")
		capabilities = append(capabilities, capabilityForScope(scope))
	}
	delegation := trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: leafID,
		SubjectPublicKey: leafEncoded, Capabilities: capabilities}
	if err := c.ctx.Err(); err != nil {
		return err
	}
	envelope, err := trust.SignDelegation(delegation, issuedAt, expiresAt, rootPrivate)
	if err != nil {
		return err
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return err
	}
	decoded, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return err
	}
	verified, err := trust.VerifyDelegationCurrent(decoded, rootKeys, now,
		trust.Policy{MaxLifetime: release.MaxDelegationLifetime, ClockSkew: time.Minute})
	if err != nil {
		return fmt.Errorf("verify current release delegation: %w", err)
	}
	if verified.SubjectKeyID() != leafID || !reflect.DeepEqual(verified.Capabilities(), capabilities) {
		return errors.New("signed release delegation differs from exact requested capabilities")
	}
	return c.writeNew(*output, wire, 0o644)
}

func sameCapabilitySet(actual, expected []trust.Capability) bool {
	if len(actual) != len(expected) {
		return false
	}
	for _, capability := range actual {
		if !slices.ContainsFunc(expected, func(other trust.Capability) bool {
			return reflect.DeepEqual(capability, other)
		}) {
			return false
		}
	}
	return true
}

func capabilityForScope(scope trust.Scope) trust.Capability {
	return trust.Capability{Domain: scope.Domain, DeploymentID: scope.DeploymentID,
		Cell: scope.Cell, Environment: scope.Environment, Role: scope.Role,
		Slots: []string{scope.Slot}, Actions: []string{"sign"}}
}

func parseDelegationUTC(value string) (time.Time, error) {
	parsed, err := time.Parse(time.RFC3339, value)
	if err != nil || parsed.Format(time.RFC3339) != value || parsed.Location() != time.UTC {
		return time.Time{}, errors.New("must be a canonical UTC RFC3339 instant ending in Z")
	}
	return parsed, nil
}

func readLeafPublicKey(path string) (ed25519.PublicKey, error) {
	data, err := readBoundedRegular(path, maxKeyFileBytes)
	if err != nil {
		return nil, err
	}
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("delegated leaf public key must be Ed25519 PKIX PEM")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse delegated leaf public key: %w", err)
	}
	public, ok := parsed.(ed25519.PublicKey)
	if !ok || len(public) != ed25519.PublicKeySize {
		return nil, errors.New("delegated leaf public key must be Ed25519")
	}
	return public, nil
}

func readOfflineRootPrivateKey(path string) (ed25519.PrivateKey, error) {
	file, err := openRegular(path)
	if err != nil {
		return nil, fmt.Errorf("open offline root signing key: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat offline root signing key: %w", err)
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("offline root signing key must be a regular owner-only file")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("offline root signing key must be owned by this process user")
	}
	if info.Size() <= 0 || info.Size() > maxKeyFileBytes {
		return nil, errors.New("offline root signing key exceeds size limit")
	}
	data, err := io.ReadAll(io.LimitReader(file, maxKeyFileBytes+1))
	if err != nil {
		return nil, fmt.Errorf("read offline root signing key: %w", err)
	}
	defer clear(data)
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PRIVATE KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("offline root signing key must be PEM PKCS#8 Ed25519")
	}
	parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse offline root signing key: %w", err)
	}
	private, ok := parsed.(ed25519.PrivateKey)
	if !ok || len(private) != ed25519.PrivateKeySize {
		return nil, errors.New("offline root signing key must be Ed25519")
	}
	return private, nil
}

func (c command) signSpecDelegationAt(args []string, now time.Time) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	flags := flag.NewFlagSet("sign-spec-delegation", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	leafPath := flags.String("subject-public-key", "", "online leaf Ed25519 PKIX public key PEM")
	rootPath := flags.String("root-key", "", "offline root Ed25519 PKIX public key PEM")
	privatePath := flags.String("signing-key", "", "owner-only offline root Ed25519 PKCS#8 private key PEM")
	var id cellspec.Identity
	flags.StringVar(&id.DeploymentID, "deployment-id", "", "deployment the delegation is bound to")
	flags.StringVar(&id.Cell, "cell", "", "cell the delegation is bound to")
	flags.StringVar(&id.Environment, "environment", "", "environment the delegation is bound to")
	issuedAtText := flags.String("issued-at", "", "canonical UTC RFC3339 issuance instant")
	expiresAtText := flags.String("expires-at", "", "canonical UTC RFC3339 expiry instant")
	output := flags.String("out", "", "new root-signed cell spec delegation")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *leafPath == "" || *rootPath == "" || *privatePath == "" || *output == "" || flags.NArg() != 0 {
		return errors.New("sign-spec-delegation requires keys, --deployment-id, --cell, --environment, a UTC interval and --out")
	}
	if err := id.Validate(); err != nil {
		return err
	}
	issuedAt, err := parseDelegationUTC(*issuedAtText)
	if err != nil {
		return fmt.Errorf("issued-at: %w", err)
	}
	expiresAt, err := parseDelegationUTC(*expiresAtText)
	if err != nil {
		return fmt.Errorf("expires-at: %w", err)
	}
	if now.IsZero() || issuedAt.After(now) || !expiresAt.After(now) ||
		!expiresAt.After(issuedAt) || expiresAt.Sub(issuedAt) > cellspec.MaxDelegationLifetime {
		return fmt.Errorf("cell spec delegation must be current and valid for no more than %s", cellspec.MaxDelegationLifetime)
	}
	leafPublic, err := readLeafPublicKey(*leafPath)
	if err != nil {
		return err
	}
	rootPublic, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	if bytes.Equal(leafPublic, rootPublic) {
		return errors.New("delegated cell spec leaf must differ from offline root")
	}
	rootPrivate, err := readOfflineRootPrivateKey(*privatePath)
	if err != nil {
		return err
	}
	defer clear(rootPrivate)
	if !bytes.Equal(rootPrivate.Public().(ed25519.PublicKey), rootPublic) {
		return errors.New("offline root signing key does not match root public key")
	}
	if err := c.ctx.Err(); err != nil {
		return err
	}
	envelope, err := cellspec.SignDelegation(leafPublic, id, issuedAt, expiresAt, rootPrivate)
	if err != nil {
		return err
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return err
	}
	if err := c.writeNew(*output, wire, 0o644); err != nil {
		return err
	}
	sum := sha256.Sum256(wire)
	return c.printJSON(struct {
		Delegation string `json:"delegation"`
		SHA256     string `json:"sha256"`
		ExpiresAt  string `json:"expires_at"`
	}{*output, hex.EncodeToString(sum[:]), expiresAt.Format(time.RFC3339)})
}

func (c command) signSpec(args []string) error {
	return c.signSpecAt(args, time.Now().UTC())
}

// signSpecAt signs an unsigned candidate written by `ts-orch service
// add|update|remove --out` or by hand. The online release leaf signs under
// its delegation; with --root the offline root signs the spec itself, which
// an amendment that widens authority needs.
func (c command) signSpecAt(args []string, now time.Time) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	flags := flag.NewFlagSet("sign-spec", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	candidate := flags.String("candidate", "", "unsigned canonical cell spec JSON")
	delegationPath := flags.String("delegation", "", "root-signed cell spec delegation envelope (leaf signing)")
	asRoot := flags.Bool("root", false, "sign with the offline root key itself instead of the delegated leaf")
	rootPath := flags.String("root-key", "", "baked root public key PEM")
	privatePath := flags.String("signing-key", "", "owner-only delegated, or with --root offline root, Ed25519 PKCS#8 private key PEM")
	validFor := flags.Duration("valid-for", time.Hour, "time the signed spec may wait to be applied")
	output := flags.String("out", "", "new signed cell spec path")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *candidate == "" || *asRoot == (*delegationPath != "") || *rootPath == "" || *privatePath == "" || *output == "" || flags.NArg() != 0 {
		return errors.New("sign-spec requires --candidate, either --delegation or --root, --root-key, --signing-key and --out")
	}
	encoded, err := readBoundedRegular(*candidate, cellspec.MaxSpecBytes)
	if err != nil {
		return err
	}
	spec, err := cellspec.Decode(encoded)
	if err != nil {
		return err
	}
	var delegationWire []byte
	if !*asRoot {
		if delegationWire, err = readBoundedRegular(*delegationPath, trust.MaxEnvelopeBytes); err != nil {
			return err
		}
		if _, err := trust.DecodeEnvelope(delegationWire); err != nil {
			return fmt.Errorf("cell spec delegation: %w", err)
		}
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	readKey := readDelegatedPrivateKey
	if *asRoot {
		readKey = readOfflineRootPrivateKey
	}
	private, err := readKey(*privatePath)
	if err != nil {
		return err
	}
	defer clear(private)
	if err := c.ctx.Err(); err != nil {
		return err
	}
	wire, err := cellspec.Sign(spec, delegationWire, roots, now, *validFor, private)
	if err != nil {
		return err
	}
	if err := c.writeNew(*output, wire, 0o644); err != nil {
		return err
	}
	sum := sha256.Sum256(wire)
	return c.printJSON(struct {
		Generation     uint64 `json:"generation"`
		RequiresBinary uint64 `json:"requires_binary"`
		Signer         string `json:"signer"`
		SHA256         string `json:"sha256"`
		DeploymentID   string `json:"deployment_id"`
		Cell           string `json:"cell"`
		Environment    string `json:"environment"`
	}{spec.Generation, spec.RequiresBinary, map[bool]string{true: "root", false: "leaf"}[*asRoot],
		hex.EncodeToString(sum[:]), spec.DeploymentID, spec.Cell, spec.Environment})
}

func (c command) printJSON(value any) error {
	encoded, err := protocol.EncodeJSON(value)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(c.output, "%s\n", encoded)
	return err
}

func mustReadFile(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func SignDelegation(leaf ed25519.PublicKey, id Identity, issuedAt, expiresAt time.Time,
	root ed25519.PrivateKey,
) (trust.Envelope, error) {
	if err := id.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if !expiresAt.After(issuedAt) || expiresAt.Sub(issuedAt) > MaxDelegationLifetime {
		return trust.Envelope{}, fmt.Errorf("cell spec delegation must expire within %s", MaxDelegationLifetime)
	}
	keyID, err := trust.KeyID(leaf)
	if err != nil {
		return trust.Envelope{}, err
	}
	encoded, err := trust.EncodeDelegatedPublicKey(leaf)
	if err != nil {
		return trust.Envelope{}, err
	}
	scope := id.Scope()
	return trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID,
		SubjectPublicKey: encoded, Capabilities: []trust.Capability{{Domain: scope.Domain,
			DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment,
			Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, issuedAt, expiresAt, root)
}

// Sign signs a spec of generation one or later and checks the result as a
// controller would, so a spec signed under a wrong or expired delegation, or
// by a key that is not a root, fails here instead of on the cell. With a
// delegation the signer is the release leaf; without one it is a root.
func Sign(spec Spec, delegationWire []byte, roots trust.Keyring, now time.Time, validFor time.Duration,
	signer ed25519.PrivateKey,
) ([]byte, error) {
	if spec.Generation == 0 {
		return nil, fmt.Errorf("%w: generation 0 is the signed controller config's spec", ErrInvalid)
	}
	if validFor <= 0 || validFor > MaxSpecLifetime {
		return nil, fmt.Errorf("cell spec validity must be positive and at most %s", MaxSpecLifetime)
	}
	payload, err := Encode(spec)
	if err != nil {
		return nil, err
	}
	issuedAt := now.Round(0).UTC().Truncate(time.Second)
	envelope, err := trust.Sign(payload, spec.Identity.Scope(), issuedAt, issuedAt.Add(validFor), signer)
	if err != nil {
		return nil, err
	}
	specWire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(Signed{Delegation: bytes.Clone(delegationWire), Spec: specWire})
	if err != nil {
		return nil, err
	}
	if _, err := VerifyCurrent(wire, roots, spec.Identity, now); err != nil {
		return nil, err
	}
	return wire, nil
}

// VerifyCurrent is the controller's admission check: currently valid
// signatures for exactly id and a valid spec of generation one or later.
func VerifyCurrent(wire []byte, roots trust.Keyring, id Identity, now time.Time) (Verified, error) {
	return verify(wire, roots, id, &now)
}

// VerifyHistorical re-checks an accepted spec without expiry: a controller
// reloads it after the signatures' validity ended. Removing the root from
// the image still revokes it.
func VerifyHistorical(wire []byte, roots trust.Keyring, id Identity) (Verified, error) {
	return verify(wire, roots, id, nil)
}

func verify(wire []byte, roots trust.Keyring, id Identity, now *time.Time) (Verified, error) {
	if err := id.Validate(); err != nil {
		return Verified{}, err
	}
	var signed Signed
	if err := protocol.DecodeStrict(wire, &signed, MaxSignedBytes); err != nil {
		return Verified{}, fmt.Errorf("decode signed cell spec: %w", err)
	}
	// One signed spec has one wire form, so its digest names it.
	if canonical, err := protocol.EncodeJSON(signed); err != nil || !bytes.Equal(canonical, wire) {
		return Verified{}, fmt.Errorf("%w: signed cell spec is not canonical JSON", ErrInvalid)
	}
	specEnvelope, err := trust.DecodeEnvelope(signed.Spec)
	if err != nil {
		return Verified{}, fmt.Errorf("cell spec envelope: %w", err)
	}
	specPolicy := trust.Policy{MaxLifetime: MaxSpecLifetime, ClockSkew: clockSkew}
	var payload []byte
	rootSigned := len(signed.Delegation) == 0
	switch {
	case rootSigned && now != nil:
		payload, err = trust.VerifyCurrent(specEnvelope, id.Scope(), roots, *now, specPolicy)
	case rootSigned:
		payload, err = trust.VerifyHistorical(specEnvelope, id.Scope(), roots, specPolicy)
	default:
		payload, err = verifyDelegated(signed.Delegation, specEnvelope, roots, id, now, specPolicy)
	}
	if err != nil {
		return Verified{}, fmt.Errorf("verify cell spec signature: %w", err)
	}
	spec, err := Decode(payload)
	if err != nil {
		return Verified{}, err
	}
	if spec.Identity != id || spec.Generation == 0 {
		return Verified{}, fmt.Errorf("%w: signed spec names another identity or generation 0", ErrInvalid)
	}
	return Verified{Spec: spec, RootSigned: rootSigned}, nil
}

func verifyDelegated(delegationWire []byte, specEnvelope trust.Envelope, roots trust.Keyring, id Identity,
	now *time.Time, specPolicy trust.Policy,
) ([]byte, error) {
	delegationEnvelope, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return nil, fmt.Errorf("delegation: %w", err)
	}
	delegationPolicy := trust.Policy{MaxLifetime: MaxDelegationLifetime, ClockSkew: clockSkew}
	if now != nil {
		delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, *now, delegationPolicy)
		if err != nil {
			return nil, fmt.Errorf("delegation: %w", err)
		}
		return trust.VerifyDelegatedCurrent(specEnvelope, id.Scope(), delegation, *now, specPolicy)
	}
	delegation, err := trust.VerifyDelegationHistorical(delegationEnvelope, roots, delegationPolicy)
	if err != nil {
		return nil, fmt.Errorf("delegation: %w", err)
	}

func (policy ReceiptPolicy) Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error) {
	if len(policy.Roots) == 0 {
		return release.VerifiedBinary{}, fmt.Errorf("%w: no release trust roots", ErrInvalid)
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	var verified release.VerifiedBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		return release.VerifiedBinary{}, fmt.Errorf("%w: self-update requires a region-qualified update receipt", release.ErrProductionQualification)
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyQualifiedBinaryUpdateCurrent(receiptWire, delegationWire, policy.Roots,
			release.UpdateExpectation{Environment: policy.Environment, Cell: policy.Cell, Architecture: policy.Architecture}, now)
	default:
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt domain %q", ErrInvalid, envelope.Scope.Domain)
	}
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	if !verified.IsVerified() || verified.Receipt().GOARCH != policy.Architecture {
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt architecture differs from this node", release.ErrExpectationMismatch)
	}
	return verified, nil
}

// Verifier is the receipt check Stage applies before any byte is kept.
type Verifier interface {
	Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error)
}

// Stage verifies the receipt, copies the binary from source while hashing
// it, requires the exact signed size and digest, and installs it read-only
// under releases/<sha256>. It is idempotent for an already staged release.
// The caller holds Layout.Lock.
func Stage(layout Layout, source io.Reader, receiptWire, delegationWire []byte, verifier Verifier, now time.Time) (string, error) {
	if source == nil || verifier == nil {
		return "", fmt.Errorf("%w: stage source and verifier are required", ErrInvalid)
	}
	verified, err := verifier.Verify(receiptWire, delegationWire, now)
	if err != nil {
		return "", fmt.Errorf("verify release receipt: %w", err)
	}
	receipt := verified.Receipt()
	if knownBad, err := layout.KnownBad(); err != nil {
		return "", err
	} else if knownBad[receipt.SHA256] {
		return "", ErrKnownBad
	}
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(receipt.SHA256)); err == nil {
		if err := layout.VerifyRelease(receipt.SHA256); err != nil {
			return "", err
		}
		return receipt.SHA256, nil
	}
	if err := layout.install(source, receipt.SHA256, receipt.Bytes, map[string][]byte{
		receiptFile: receiptWire, delegationFile: delegationWire,
	}); err != nil {
		return "", err
	}
	return receipt.SHA256, nil
}

// ReleaseReceipt returns the signed receipt and delegation a staged release

func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

type httpError int

func (err httpError) Error() string          { return fmt.Sprintf("HTTP %d", int(err)) }
func (err httpError) GetHTTPStatusCode() int { return int(err) }

// regionBucket is a region's head bucket whose leader verifies the channel
// as a controller would and then reports outcome for it.
type regionBucket struct {
	mu      sync.Mutex
	cell    string
	roots   trust.Keyring
	outcome releasechannel.State
	objects map[string][]byte
	scope   *releasechannel.Status
	log     *[]string
	logMu   *sync.Mutex
	wait    func(context.Context) error
}

func (bucket *regionBucket) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	data, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	bucket.mu.Lock()
	defer bucket.mu.Unlock()
	name := *request.ObjectName
	if _, exists := bucket.objects[name]; exists && request.IfNoneMatch != nil {
		return objectstorage.PutObjectResponse{}, httpError(412)
	}
	bucket.objects[name] = data
	bucket.logMu.Lock()
	*bucket.log = append(*bucket.log, "put "+bucket.cell+" "+name)
	bucket.logMu.Unlock()
	return objectstorage.PutObjectResponse{}, nil
}

func (bucket *regionBucket) GetObject(ctx context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	if *request.ObjectName == releasechannel.StatusObject && bucket.wait != nil {
		if err := bucket.wait(ctx); err != nil {
			return objectstorage.GetObjectResponse{}, err
		}
	}
	bucket.mu.Lock()
	defer bucket.mu.Unlock()
	name := *request.ObjectName
	data, ok := bucket.objects[name]
	if name == releasechannel.StatusObject && !ok {
		data, ok = bucket.status()
		if !ok && bucket.scope != nil {
			data, _ = json.Marshal(bucket.scope)
			ok = true
		}
	}
	if !ok {
		return objectstorage.GetObjectResponse{}, httpError(404)
	}
	return objectstorage.GetObjectResponse{Content: io.NopCloser(bytes.NewReader(data)), ETag: new(fmt.Sprintf("%x", len(data)))}, nil
}

// status is what the region's leader reports once it read the channel: it
// fails the release if the channel does not verify for its own cell.
func (bucket *regionBucket) status() ([]byte, bool) {
	wire, ok := bucket.objects[releasechannel.ChannelObject]
	if !ok {
		return nil, false
	}
	var channel releasechannel.Channel
	if err := json.Unmarshal(wire, &channel); err != nil {
		return nil, false
	}
	status := releasechannel.Status{Schema: releasechannel.StatusSchema, Cell: bucket.cell,
		SourceRevision: channel.SourceRevision, RunNumber: channel.RunNumber, State: bucket.outcome, UpdatedAt: time.Now()}
	verified, err := channel.Verify(bucket.roots, bucket.cell, "production", time.Now())
	if err == nil {
		for _, binary := range verified {
			if _, ok := bucket.objects[releasechannel.BinaryObject(binary.Receipt().SHA256)]; !ok {
				err = errors.New("binary missing")
			}
		}
	}
	if err != nil {
		status.State, status.Reason = releasechannel.StateFailed, err.Error()
	}
	encoded, _ := json.Marshal(status)
	return encoded, true
}

