	}
	return args
}

func (fixture *deployFixture) touched(cell string) bool {
	for _, entry := range fixture.log {
		if strings.HasPrefix(entry, "put "+cell+" ") {
			return true
		}
	}
	return false
}

type deployEnv struct {
	// timeout shortens the fixed observation budget in tests.
	timeout time.Duration
	check   func(release.Qualification, string) error
	inspect func(string, string, string) (binaryReceipt, error)
	git     func(context.Context, ...string) (string, error)
	// storage returns the Object Storage client of a cell's region.
	storage func(cell string) (releasechannel.ObjectClient, error)
	// secret reads one Vault secret.
	secret   func(ctx context.Context, vaultID, name string) ([]byte, error)
	discover func(context.Context) ([]string, error)
}

func (c command) deploy(args []string) error {
	return c.deployWith(args, deployEnv{check: c.verifyGitHubQualification, inspect: c.inspectBinary, git: runGit,
		storage: operatorObjectStorage, secret: readVaultSecret, discover: discoverServingCells})
}

// deployWith signs and deploys one CI-qualified release independently in
// every cell with the online update leaf. Each cell owns
// its quorum, health gates and rollback. A failed cell fails the command
// after every other started deployment has finished.
func (c command) deployWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("deploy", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	directory := flags.String("dir", "", "retained CI release: qualification.json and terrascale-orchestrator-linux-<arch>")
	evidenceDir := flags.String("production-evidence-dir", "", "retained signed runtime and workload evidence; default DIR/production")
	sourceRevision := flags.String("source-revision", "", "expected exact Git revision")
	delegationPath := flags.String("update-delegation", "", "root-signed binary update delegation")
	delegationSecret := flags.String("update-delegation-secret", "", "OCI Vault secret holding the root-signed release delegation, instead of --update-delegation")
	rootPath := flags.String("root-key", "", "root public key PEM")
	keyPath := flags.String("signing-key", "", "owner-only update leaf Ed25519 PKCS#8 private key PEM")
	keySecret := flags.String("signing-key-secret", "", "OCI Vault secret holding the update leaf key, instead of --signing-key")
	vaultID := flags.String("vault-id", "", "OCI Vault of --signing-key-secret and --update-delegation-secret")
	environment := flags.String("environment", "", "production or canary; default the region's admitted scope")
	checkout := flags.String("source-checkout", "", "repository checkout used to prove lineage")
	namespace := flags.String("namespace", "", "Object Storage namespace of the regions' head buckets")
	validFor := flags.Duration("valid-for", 7*24*time.Hour, "receipt validity, bounded by delegation expiry")
	poll := flags.Duration("poll", 30*time.Second, "how often a cell's status is read")
	var cells, architectures stringList
	flags.Var(&cells, "cell", "cell to deploy to concurrently; repeatable; default every serving cell")
	flags.Var(&architectures, "arch", "amd64 or arm64; repeatable; default each region's architectures")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *directory == "" || !release.ValidSourceRevision(*sourceRevision) || (*delegationPath == "") == (*delegationSecret == "") || *rootPath == "" ||
		(*keyPath == "") == (*keySecret == "") || (*keySecret == "" && *delegationSecret == "") != (*vaultID == "") ||
		*environment != "" && !validEnvironment(*environment) || *checkout == "" || !validStorageToken(*namespace) ||
		*poll <= 0 || flags.NArg() != 0 {
		return errors.New("deploy requires --dir, --source-revision, --update-delegation or --update-delegation-secret, --root-key, --signing-key or --signing-key-secret, --vault-id with any secret, --source-checkout and --namespace")
	}
	targetCells, err := deploymentCells(c.ctx, cells, env.discover)
	if err != nil {
		return err
	}
	cells = targetCells
	for _, architecture := range architectures {
		if architecture != "amd64" && architecture != "arm64" {
			return fmt.Errorf("unsupported architecture %q", architecture)
		}
	}
	qualification, qualificationDigest, err := readQualification(filepath.Join(*directory, "qualification.json"))
	if err != nil {
		return err
	}
	if qualification.SourceRevision != *sourceRevision {
		return errors.New("qualification names another source revision")
	}
	if err := env.check(qualification, qualificationDigest); err != nil {
		return err
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	if *evidenceDir == "" {
		*evidenceDir = filepath.Join(*directory, "production")
	}
	regionTimeout := rollout.ObservationBudget
	if env.timeout > 0 {
		regionTimeout = min(regionTimeout, env.timeout)
	}
	progress := &deploymentWriter{Writer: c.output}
	type signingCredentials struct {
		delegation trust.Envelope
		private    ed25519.PrivateKey
	}
	credentials := sync.OnceValues(func() (signingCredentials, error) {
		var delegation trust.Envelope
		var err error
		if *delegationPath != "" {
			delegation, err = readEnvelope(*delegationPath)
		} else {
			var data []byte
			if data, err = env.secret(c.ctx, *vaultID, *delegationSecret); err == nil {
				delegation, err = trust.DecodeEnvelope(data)
			}
		}
		if err != nil {
			return signingCredentials{}, fmt.Errorf("read the update delegation: %w", err)
		}
		var private ed25519.PrivateKey
		if *keyPath != "" {
			private, err = readDelegatedPrivateKey(*keyPath)
		} else {
			var data []byte
			if data, err = env.secret(c.ctx, *vaultID, *keySecret); err == nil {
				private, err = parseDelegatedPrivateKey(data)
				clear(data)
			}
		}
		if err != nil {
			return signingCredentials{}, fmt.Errorf("read the update leaf key: %w", err)
		}
		return signingCredentials{delegation, private}, nil
	})
	var private ed25519.PrivateKey
	defer func() { clear(private) }()

	started := time.Now()
	lineage := &deploymentLineage{checker: gitLineage{ctx: c.ctx, checkout: *checkout, run: env.git},
		results: make(map[[3]string]error)}
	var regions errgroup.Group
	regions.SetLimit(4)
	var failureMu sync.Mutex
	var failures []error
	preflights := c.prepareDeploymentTargets(*directory, *evidenceDir, *namespace, *environment,
		cells, architectures, qualification, qualificationDigest, roots, regionTimeout, env, progress)
	for result := range preflights {
		if result.err != nil {
			failureMu.Lock()
			failures = append(failures, result.err)
			failureMu.Unlock()
			continue
		}
		target := result.target
		regions.Go(func() (regionErr error) {
			ctx, cancel := context.WithTimeout(c.ctx, regionTimeout)
			defer cancel()
			regional := c
			regional.ctx = ctx
			deadline := time.Now().UTC().Add(regionTimeout)
			cell := target.cell
			defer func() {
				if regionErr != nil {
					failureMu.Lock()
					failures = append(failures, fmt.Errorf("%s: %w", cell, regionErr))
					failureMu.Unlock()
					fmt.Fprintf(progress, "%s failed: %v\n", cell, regionErr)
				}
			}()
			cellStarted := time.Now()
			location, cellEnvironment, cellArchitectures, binaries := target.location, target.environment, target.architectures, target.binaries
			if err := regional.verifyProductionArtifacts(*evidenceDir, roots, cell, cellEnvironment, binaries, deadline); err != nil {
				return err
			}
			keys, err := credentials()
			if err != nil {
				return err
			}
			failureMu.Lock()
			private = keys.private
			failureMu.Unlock()
			delegationWire, err := trust.EncodeEnvelope(keys.delegation)
			if err != nil {
				return err
			}
			channel := releasechannel.Channel{Schema: releasechannel.ChannelSchema, Cell: cell, Environment: cellEnvironment,
				SourceRevision: *sourceRevision, RunNumber: qualification.Verification.RunNumber, Delegation: delegationWire}
			for _, architecture := range cellArchitectures {
				envelope, err := release.SignBinaryUpdateReceipt(binaries[architecture], qualification, qualificationDigest, cell,
					cellEnvironment, lineage, keys.delegation, roots, keys.private, cellStarted.UTC(), *validFor)
				if err != nil {
					return fmt.Errorf("sign %s: %w", architecture, err)
				}
				proof, err := readProductionProof(*evidenceDir, cell, architecture)
				if err != nil {
					return err
				}
				envelope, err = release.AttachProductionQualification(envelope, proof, delegationWire, roots, keys.private,
					release.UpdateExpectation{Environment: cellEnvironment, Cell: cell, Architecture: architecture}, cellStarted.UTC())
				if err != nil {
					return err
				}
				wire, err := trust.EncodeEnvelope(envelope)
				if err != nil {
					return err
				}
				channel.Receipts = append(channel.Receipts, wire)
			}
			// Receipts must remain valid through the shared rollout deadline.
			if _, err := channel.Verify(roots, cell, cellEnvironment, deadline); err != nil {
				return fmt.Errorf("receipts would expire during rollout; renew the update delegation: %w", err)
			}
			for _, architecture := range cellArchitectures {
				if err := regional.uploadBinary(location, binaryPath(*directory, architecture), binaries[architecture].SHA256); err != nil {
					return fmt.Errorf("upload the %s binary to %s: %w", architecture, channel.Cell, err)
				}
			}
			if err := releasechannel.Publish(ctx, location, channel); err != nil {
				return fmt.Errorf("publish to %s: %w", channel.Cell, err)
			}
			fmt.Fprintf(progress, "%s published: run %d %s\n", channel.Cell, channel.RunNumber, channel.SourceRevision)
			if err := releasechannel.Await(ctx, location, channel, *poll, deadline, progress); err != nil {
				return err
			}
			fmt.Fprintf(progress, "%s rolled out in %s\n", channel.Cell, time.Since(cellStarted).Round(time.Second))
			return nil
		})
	}
	// Do not cancel a healthy cell's rollout when another cell rolls back.
	_ = regions.Wait()
	if err := errors.Join(failures...); err != nil {
		return fmt.Errorf("fleet rollout failed: %w", err)
	}
	_, err = fmt.Fprintf(c.output, "fleet complete: run %d %s in %s after %s\n", qualification.Verification.RunNumber,
		*sourceRevision, strings.Join(cells, " "), time.Since(started).Round(time.Second))
	return err
}

func (c command) prepareDeploymentTargets(directory, evidenceDir, namespace, environment string,
	cells, architectures []string, qualification release.Qualification, qualificationDigest string,
	roots trust.Keyring, budget time.Duration, env deployEnv, progress io.Writer,
) <-chan deploymentPreflightResult {
	results := make(chan deploymentPreflightResult)
	go func() {
		defer close(results)
		inspected := make(map[string]binaryReceipt)
		var inspection sync.Mutex
		var regions errgroup.Group
		regions.SetLimit(4)
		for _, cell := range cells {
			regions.Go(func() error {
				ctx, cancel := context.WithTimeout(c.ctx, budget)
				defer cancel()
				regional := c
				regional.ctx = ctx
				target := deploymentTarget{cell: cell, environment: environment, architectures: architectures}
				admit := func() error {
					if target.environment == "" || len(target.architectures) == 0 {
						location, err := channelLocation(env, cell, namespace)
						if err != nil {
							return err
						}
						scope, err := deploymentScope(ctx, location, cell)
						if err != nil {
							return err
						}
						if target.environment == "" {
							target.environment = scope.Environment
						}
						if len(target.architectures) == 0 {
							target.architectures = scope.Architectures
						}
						target.location = location
					}
					target.binaries = make(map[string]binaryReceipt, len(target.architectures))
					for _, architecture := range target.architectures {
						inspection.Lock()
						receipt, found := inspected[architecture]
						var err error
						if !found {
							receipt, err = env.inspect(binaryPath(directory, architecture), qualification.GoVersion, qualification.SourceRevision)
							if err == nil {
								inspected[architecture] = receipt
							}
						}
						inspection.Unlock()
						if err != nil {
							return err
						}
						receipt.QualificationSHA256 = qualificationDigest
						if err := qualification.MatchBinary(receipt, qualificationDigest); err != nil {
							return err
						}
						if receipt.GOARCH != architecture {
							return fmt.Errorf("%s binary is built for %s", architecture, receipt.GOARCH)
						}
						target.binaries[architecture] = receipt
					}
					if err := regional.verifyProductionArtifacts(evidenceDir, roots, cell, target.environment, target.binaries, time.Now().UTC().Add(budget)); err != nil {
						return err
					}
					if target.location.Client == nil {
						location, err := channelLocation(env, cell, namespace)
						if err != nil {
							return err
						}
						target.location = location
					}
					return nil
				}
				err := admit()
				if err != nil {
					err = fmt.Errorf("%s: %w", cell, err)
					fmt.Fprintf(progress, "%s qualification refused: %v\n", cell, err)
				}
				select {
				case results <- deploymentPreflightResult{target, err}:
				case <-c.ctx.Done():
				}
				return nil
			})
		}
		_ = regions.Wait()
	}()
	return results
}

func deploymentScope(ctx context.Context, location releasechannel.Location, cell string) (releasechannel.Status, error) {
	scope, found, err := releasechannel.ReadStatus(ctx, location)
	if err != nil {
		return scope, fmt.Errorf("read deployment scope: %w", err)
	}
	if !found {
		return scope, errors.New("regional deployment scope is missing; deploy its producer before the discovery consumer")
	}
	return scope, scope.ValidateDeploymentScope(cell, time.Now().UTC())
}

func SignBinaryReceipt(receipt BinaryReceipt, environment string, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := validateEnvironment(environment); err != nil {
		return trust.Envelope{}, err
	}
	return signReceipt(receipt, BinaryScope(receipt, environment), delegation, roots, privateKey, now, validFor)
}

// SignImageReceipt verifies a current root delegation, applies the release
// signing lifetime limits, signs the canonical payload, and re-verifies the
// result through the consumer policy before returning it.
func SignImageReceipt(receipt ImageReceipt, environment string, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := validateEnvironment(environment); err != nil {
		return trust.Envelope{}, err
	}
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and at most %s", MaxReceiptLifetime)
	}
	productionExpiry, err := verifyImageProduction(receipt, environment, roots, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if validFor > 0 && productionExpiry.Before(now.Add(validFor)) {
		validFor = productionExpiry.Sub(now)
	}
	return signReceipt(receipt, ImageScope(receipt, environment), delegation, roots, privateKey, now, validFor)
}

// VerifyBinaryCurrent verifies a canonical receipt wire, a currently valid
// root-signed delegation, the exact signer capability, and the environment.
func VerifyBinaryCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected BinaryExpectation, now time.Time,
) (VerifiedBinary, error) {
	if err := validateEnvironment(expected.Environment); err != nil {
		return VerifiedBinary{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	receipt, err := decodeCanonicalPayload[BinaryReceipt](envelope.Payload)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedBinary{}, err
	}
	scope := BinaryScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedBinary{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedBinary{}, fmt.Errorf("verify current signed binary receipt: %w", err)
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedBinary{}, err
	}
	return VerifiedBinary{receipt: receipt, proof: proof}, nil
}

func VerifyImageCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation, now time.Time,
) (VerifiedImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return VerifiedImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return VerifiedImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return VerifiedImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current signed image receipt: %w", err)
	}
	productionExpiry, err := verifyImageProduction(receipt, expected.Environment, roots, now)
	if err != nil {
		return VerifiedImage{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedImage{}, err
	}
	if productionExpiry.Before(proof.expiresAt) {
		proof.expiresAt = productionExpiry
	}
	return VerifiedImage{receipt: receipt, proof: proof}, nil
}

type containerHTTPFixture struct {
	*applyHTTPFixture
	allocations release.SequenceLocation
}

func (f *containerHTTPFixture) serveContainer(w http.ResponseWriter, r *http.Request) {
	parts := strings.SplitN(r.URL.Path, "/", 7)
	if len(parts) != 7 || r.Header.Get("Authorization") == "" {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	cell, _, _ := strings.Cut(strings.ToUpper(parts[4]), "-")
	name := parts[6]
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.objects[cell] == nil {
		f.objects[cell] = map[string][]byte{}
	}
	if r.Method == http.MethodPut {
		if cell == "SFO" && f.failure == "storage" {
			w.WriteHeader(http.StatusForbidden)
			return
		}
		old, exists := f.objects[cell][name]
		sum := sha256.Sum256(old)
		if r.Header.Get("If-None-Match") == "*" && exists || r.Header.Get("If-Match") != "" && r.Header.Get("If-Match") != fmt.Sprintf("%x", sum) {
			w.WriteHeader(http.StatusPreconditionFailed)
			return
		}
		data, err := io.ReadAll(r.Body)
		if err != nil {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		f.objects[cell][name] = data
		if strings.HasSuffix(name, "/container.json") {
			f.channelWrites[cell]++
		}
		sum = sha256.Sum256(data)
		w.Header().Set("etag", fmt.Sprintf("%x", sum))
		return
	}
	data, exists := f.objects[cell][name]
	if name == releasechannel.StatusObject {
		data, _ = json.Marshal(releasechannel.Status{Schema: releasechannel.StatusSchema, Cell: cell, Environment: "production", Architectures: []string{"arm64"}, UpdatedAt: time.Now().UTC()})
		exists = true
	}
	if name == releasechannel.ContainerStatusObject("ts-auth", "amd64") {
		if wire, found := f.objects[cell][releasechannel.ContainerReleaseObject("ts-auth", "amd64")]; found {
			var bundle release.ContainerBundle
			if err := json.Unmarshal(wire, &bundle); err != nil {
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			scope := release.ContainerTarget{Cell: cell, Environment: "production", Role: "ts-auth", Architecture: "amd64"}
			now := time.Now().UTC()
			f.mu.Unlock()
			verified, err := release.VerifyContainerCurrent(r.Context(), bundle, f.roots, scope, now, now.Add(time.Millisecond), func(_ context.Context, digest string) (io.ReadCloser, error) {
				f.mu.Lock()
				defer f.mu.Unlock()
				content, ok := f.objects[cell][releasechannel.ContainerEvidenceObject("ts-auth", digest)]
				if !ok {
					return nil, os.ErrNotExist
				}
				return io.NopCloser(bytes.NewReader(content)), nil
			}, f.allocations)
			f.mu.Lock()
			if err != nil {
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			claim := verified.Claim()
			data, _ = json.Marshal(releasechannel.ContainerStatus{Schema: releasechannel.ContainerStatusSchema, Cell: cell, Environment: claim.Environment, Role: claim.Role, Architecture: claim.Architecture, Image: claim.Image, ReleaseSequence: claim.ReleaseSequence, Fingerprint: verified.Fingerprint(), State: releasechannel.StateComplete, UpdatedAt: now})
			exists = true
		}
	}
	if !exists {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	sum := sha256.Sum256(data)
	w.Header().Set("etag", fmt.Sprintf("%x", sum))
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(data)
}

func containerCLIImageLayout(t *testing.T) (string, string, map[string]string) {
	t.Helper()
	directory := t.TempDir()
	if err := os.MkdirAll(filepath.Join(directory, "blobs", "sha256"), 0o700); err != nil {
		t.Fatal(err)
	}
	encode := func(value any) []byte {
		t.Helper()
		wire, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		return wire
	}
	blob := func(wire []byte, media string) ocispec.Descriptor {
		t.Helper()
		sum := digest.FromBytes(wire)
		writeFixtureFile(t, filepath.Join(directory, "blobs", "sha256", sum.Encoded()), wire, 0o600)
		return ocispec.Descriptor{MediaType: media, Digest: sum, Size: int64(len(wire))}
	}
	var layer bytes.Buffer
	archive := tar.NewWriter(&layer)
	contents := []byte("#!/bin/sh\nexit 0\n")
	if err := archive.WriteHeader(&tar.Header{Name: "service", Mode: 0o755, Size: int64(len(contents))}); err != nil {
		t.Fatal(err)
	}
	if _, err := archive.Write(contents); err != nil {
		t.Fatal(err)
	}
	if err := archive.Close(); err != nil {
		t.Fatal(err)
	}
	layerDescriptor := blob(layer.Bytes(), ocispec.MediaTypeImageLayer)
	children := make(map[string]string)
	index := ocispec.Index{SchemaVersion: 2, MediaType: ocispec.MediaTypeImageIndex}
	for _, architecture := range []string{"amd64", "arm64"} {
		platform := ocispec.Platform{OS: "linux", Architecture: architecture}
		config := ocispec.Image{Platform: platform, RootFS: ocispec.RootFS{Type: "layers", DiffIDs: []digest.Digest{layerDescriptor.Digest}}}
		manifest := ocispec.Manifest{SchemaVersion: 2, MediaType: ocispec.MediaTypeImageManifest, Config: blob(encode(config), ocispec.MediaTypeImageConfig), Layers: []ocispec.Descriptor{layerDescriptor}}
		child := blob(encode(manifest), ocispec.MediaTypeImageManifest)
		child.Platform = &platform
		index.Manifests = append(index.Manifests, child)
		children[architecture] = child.Digest.Encoded()
	}
	root := ocispec.Descriptor{Digest: digest.FromBytes(encode(index))}
	writeFixtureFile(t, filepath.Join(directory, "index.json"), encode(index), 0o600)
	writeFixtureFile(t, filepath.Join(directory, "oci-layout"), []byte(`{"imageLayoutVersion":"1.0.0"}`), 0o600)
	return directory, "registry.example/terrascale/auth@" + root.Digest.String(), children
}

func serviceMigrationFixture(t *testing.T, base *applyHTTPFixture, role string, public ed25519.PublicKey, now time.Time) []byte {
	t.Helper()
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	migration := release.SequenceMigration{Schema: release.SequenceMigrationSchema, Namespace: "ns", Bucket: "gru-1-head", Region: "GRU",
		SignerKeyID: keyID, SignerPublicKey: encoded, Role: role, Environment: "production", SequenceFloor: 1}
	for _, cell := range []string{"FRA", "GRU", "SFO"} {
		migration.Regions = append(migration.Regions, release.SequenceFloor{Cell: cell, RunNumber: 1, IssuedAt: now.Add(-time.Minute), EvidenceSHA256: base.binary.SHA256})
	}
	envelope, err := release.SignSequenceMigration(migration, now.Add(-time.Minute), base.rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func (c command) containerBundleWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("container-bundle", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	directory := flags.String("dir", "", "output signed container bundle")
	layout := flags.String("oci-layout", "", "retained standard OCI Image Layout directory")
	image := flags.String("image", "", "canonical repository@sha256:root from CI")
	role := flags.String("role", "", "first-party service role")
	repository := flags.String("repository", "", "HTTPS source repository")
	commit := flags.String("commit", "", "exact source revision")
	checkout := flags.String("source-checkout", "", "checkout proving exact source tree")
	environment := flags.String("environment", "", "admitted environment")
	rootPath := flags.String("root-key", "", "existing trusted root public key PEM")
	delegationPath := flags.String("delegation", "", "root-signed OCI release delegation")
	migrationPath := flags.String("sequence-migration", "", "root-signed signer sequence migration")
	evidenceDir := flags.String("production-evidence-dir", "", "retained independent production evidence")
	keyPath := flags.String("signing-key", "", "owner-only delegated Ed25519 private key PEM")
	keySecret := flags.String("signing-key-secret", "", "existing OCI Vault signing secret")
	vaultID := flags.String("vault-id", "", "existing OCI Vault")
	var cells, architectures stringList
	flags.Var(&cells, "cell", "target cell; default every discovered serving cell")
	flags.Var(&architectures, "arch", "target architecture; default both Linux architectures")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *directory == "" || *layout == "" || *image == "" || *role == "" || *repository == "" || !release.ValidSourceRevision(*commit) || *checkout == "" || !validEnvironment(*environment) || *rootPath == "" || *delegationPath == "" || *migrationPath == "" || *evidenceDir == "" || (*keyPath == "") == (*keySecret == "") || (*keySecret == "") != (*vaultID == "") || flags.NArg() != 0 {
		return errors.New("container-bundle requires --dir, --oci-layout, --image, --role, --repository, --commit, --source-checkout, --environment, --root-key, --delegation, --sequence-migration, --production-evidence-dir and one signing key source")
	}
	cells, err := deploymentCells(c.ctx, cells, env.discover)
	if err != nil {
		return err
	}
	if len(architectures) == 0 {
		architectures = []string{"amd64", "arm64"}
	}
	slices.Sort(cells)
	slices.Sort(architectures)
	for index, architecture := range architectures {
		if !slices.Contains([]string{"amd64", "arm64"}, architecture) || index > 0 && architectures[index-1] == architecture {
			return errors.New("unsupported or duplicate OCI architecture")
		}
	}
	tree, err := release.SourceTreeDigest(c.ctx, *checkout, *commit)
	if err != nil {
		return err
	}
	// The existing source validator enforces an HTTPS repository and exact tree.
	source := containerSource{Repository: *repository, Commit: *commit, TreeDigest: tree}
	if err := validateContainerSource(source); err != nil {
		return err
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	delegationWire, err := readBoundedRegular(*delegationPath, trust.MaxEnvelopeBytes)
	if err != nil {
		return err
	}
	grant, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return err
	}
	now := time.Now().UTC()
	deadline := now.Add(rollout.ObservationBudget)
	delegation, err := trust.VerifyDelegationCurrent(grant, roots, deadline, trust.Policy{MaxLifetime: release.MaxUpdateReceiptLifetime})
	if err != nil {
		return err
	}
	migrationWire, err := readBoundedRegular(*migrationPath, trust.MaxEnvelopeBytes)
	if err != nil {
		return err
	}
	migrationEnvelope, err := trust.DecodeEnvelope(migrationWire)
	if err != nil {
		return err
	}
	migration, err := release.VerifySequenceMigrationHistorical(migrationEnvelope, roots, *role, *environment)
	if err != nil {
		return err
	}
	migrationSHA, err := trust.Fingerprint(migrationEnvelope)
	if err != nil {
		return err
	}
	type candidate struct {
		claim  release.ContainerClaim
		bundle release.ContainerBundle
	}
	targets := make([]candidate, 0, len(cells)*len(architectures))
	for _, architecture := range architectures {
		inspected, err := release.InspectContainerImageLayout(c.ctx, *layout, *image, architecture)
		if err != nil {
			return err
		}
		qualification := inspected.IndexSHA256
		if qualification == "" {
			qualification = inspected.ManifestSHA256
		}
		for _, cell := range cells {
			claim := release.ContainerClaim{Schema: release.ContainerClaimSchema, Image: inspected.Image, SourceRevision: *commit, SourceRepository: *repository, SourceTreeSHA256: tree, Cell: cell, Environment: *environment, Role: *role, Architecture: architecture, QualificationSHA256: qualification}
			scope := release.ContainerScope(release.ContainerTarget{Cell: cell, Environment: *environment, Role: *role, Architecture: architecture})
			if !containerDelegationAllows(delegation, scope) {
				return errors.New("OCI candidate exceeds its root signing capability")
			}
			expected := release.ProductionExpectation{SourceRevision: *commit, ArtifactSHA256: inspected.ManifestSHA256, QualificationSHA256: qualification, Cell: cell, Environment: *environment, Runtime: release.ProductionRuntime, Architecture: architecture, Role: *role}
			if err := c.verifyProductionCandidate(*evidenceDir, roots, expected, deadline); err != nil {
				return err
			}
			claim.Production, err = readProductionProof(*evidenceDir, cell, architecture)
			if err != nil {
				return err
			}
			targets = append(targets, candidate{claim: claim, bundle: release.ContainerBundle{Delegation: delegationWire, Migration: migrationWire}})
		}
	}
	var private ed25519.PrivateKey
	if *keyPath != "" {
		private, err = readDelegatedPrivateKey(*keyPath)
	} else {
		var data []byte
		data, err = env.secret(c.ctx, *vaultID, *keySecret)
		if err == nil {
			private, err = parseDelegatedPrivateKey(data)
		}
		clear(data)
	}
	if err != nil {
		return err
	}
	defer clear(private)
	signerID, err := trust.KeyID(private.Public().(ed25519.PublicKey))
	if err != nil {
		return err
	}
	if signerID != delegation.SubjectKeyID() || signerID != migration.SignerKeyID {
		return trust.ErrKeyMismatch
	}
	deadline = time.Now().UTC().Add(rollout.ObservationBudget)
	if _, err := trust.VerifyDelegationCurrent(grant, roots, deadline, trust.Policy{MaxLifetime: release.MaxUpdateReceiptLifetime}); err != nil {
		return err
	}
	for _, target := range targets {
		_, child, _ := strings.Cut(target.claim.Image, "@sha256:")
		expected := release.ProductionExpectation{SourceRevision: target.claim.SourceRevision, ArtifactSHA256: child, QualificationSHA256: target.claim.QualificationSHA256, Cell: target.claim.Cell, Environment: target.claim.Environment, Runtime: release.ProductionRuntime, Architecture: target.claim.Architecture, Role: target.claim.Role}
		if err := c.verifyProductionCandidate(*evidenceDir, roots, expected, deadline); err != nil {
			return err
		}
	}
	client, err := env.storage(migration.Region)
	if err != nil {
		return err
	}
	location := release.SequenceLocation{Client: client, Namespace: migration.Namespace, Bucket: migration.Bucket}
	if err := location.ImportMigration(c.ctx, migrationEnvelope, roots, *role, *environment, now); err != nil {
		return err
	}
	family, err := targets[0].claim.WorkerFamilyDigest()
	if err != nil {
		return err
	}
	for _, target := range targets[1:] {
		candidate, err := target.claim.WorkerFamilyDigest()
		if err != nil {
			return err
		}
		if candidate != family {
			return errors.New("container targets do not share one source and OCI index family")
		}
	}
	sequence, reservation, err := location.AllocateWithEvidence(c.ctx, release.SequenceIdentity{Role: *role, Environment: *environment, SourceRevision: *commit, ManifestSHA256: family}, roots, private)
	if err != nil {
		return err
	}
	issued := time.Now().UTC()
	expires := grant.ExpiresAt
	if !deadline.Before(expires) {
		return errors.New("container delegation expires before operation deadline")
	}
	for index := range targets {
		target := &targets[index]
		target.bundle.Sequence = slices.Clone(reservation)
		target.claim.ReleaseSequence = sequence
		target.claim.SequenceMigrationSHA256 = migrationSHA
		payload, err := trust.EncodePayload(target.claim)
		if err != nil {
			return err
		}
		scope := release.ContainerTarget{Cell: target.claim.Cell, Environment: *environment, Role: *role, Architecture: target.claim.Architecture}
		envelope, err := trust.Sign(payload, release.ContainerScope(scope), issued, expires, private)
		if err != nil {
			return err
		}
		target.bundle.Claim, err = trust.EncodeEnvelope(envelope)
		if err != nil {
			return err
		}
		if _, err := release.VerifyContainerCurrent(c.ctx, target.bundle, roots, scope, issued, deadline, containerEvidenceReader(*evidenceDir), location); err != nil {
			return err
		}
	}
	if err := os.MkdirAll(*directory, 0o700); err != nil {
		return err
	}
	for _, target := range targets {
		destination := filepath.Join(*directory, target.claim.Cell, target.claim.Architecture)
		if err := os.MkdirAll(destination, 0o700); err != nil {
			return err
		}
		wire, err := json.Marshal(target.bundle, json.Deterministic(true))
		if err != nil {
			return err
		}
		if len(wire) > releasechannel.MaxContainerBundleBytes {
			return errors.New("signed OCI bundle exceeds durable intent bound")
		}
		if err := c.writeNew(filepath.Join(destination, "container.json"), wire, 0o600); err != nil {
			return err
		}
	}
	if filepath.Clean(*evidenceDir) != filepath.Join(filepath.Clean(*directory), "production") {
		if err := os.CopyFS(filepath.Join(*directory, "production"), os.DirFS(*evidenceDir)); err != nil {
			return fmt.Errorf("retain container evidence: %w", err)
		}
	}
	if filepath.Clean(*layout) != filepath.Join(filepath.Clean(*directory), "oci-layout") {
		if err := os.CopyFS(filepath.Join(*directory, "oci-layout"), os.DirFS(*layout)); err != nil {
			return fmt.Errorf("retain standard OCI layout: %w", err)
		}
	}
	_, err = fmt.Fprintf(c.output, "%s signed OCI container bundle: sequence %d %s\n", *role, sequence, *directory)
	return err
}

func (c command) containerApplyWith(args []string, env deployEnv) error {
	flags := flag.NewFlagSet("container-apply", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	directory := flags.String("dir", "", "retained signed container bundle with OCI layout and evidence")
	rootPath := flags.String("root-key", "", "existing trusted root public key outside the bundle")
	namespace := flags.String("namespace", "", "regional Object Storage namespace")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *directory == "" || *rootPath == "" || !validStorageToken(*namespace) || flags.NArg() != 0 {
		return errors.New("container-apply requires --dir, --root-key and --namespace")
	}
	root, err := readRootPublicKey(*rootPath)
	if err != nil {
		return err
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(*directory)
	if err != nil {
		return err
	}
	type target struct {
		bundle      release.ContainerBundle
		verified    release.VerifiedContainer
		scope       release.ContainerTarget
		allocations release.SequenceLocation
	}
	targets := make(map[string][]target)
	var cells []string
	var source, repository, tree, role, environment string
	var sequence uint64
	budget := rollout.ObservationBudget
	if env.timeout > 0 {
		budget = min(budget, env.timeout)
	}
	now := time.Now().UTC()
	deadline := now.Add(budget)
	for _, entry := range entries {
		if !entry.IsDir() || !validRegion(entry.Name()) {
			continue
		}
		architectures, err := os.ReadDir(filepath.Join(*directory, entry.Name()))
		if err != nil {
			return err
		}
		for _, architecture := range architectures {
			if !architecture.IsDir() || !slices.Contains([]string{"amd64", "arm64"}, architecture.Name()) {
				continue
			}
			wire, err := readBoundedRegular(filepath.Join(*directory, entry.Name(), architecture.Name(), "container.json"), releasechannel.MaxContainerBundleBytes)
			if err != nil {
				return err
			}
			var bundle release.ContainerBundle
			if err := protocol.DecodeStrict(wire, &bundle, releasechannel.MaxContainerBundleBytes); err != nil {
				return err
			}
			envelope, err := trust.DecodeEnvelope(bundle.Claim)
			if err != nil {
				return err
			}
			var claim release.ContainerClaim
			if err := protocol.DecodeStrict(envelope.Payload, &claim, trust.MaxPayloadBytes); err != nil {
				return err
			}
			scope := release.ContainerTarget{Cell: entry.Name(), Environment: claim.Environment, Role: claim.Role, Architecture: architecture.Name()}
			migrationEnvelope, err := trust.DecodeEnvelope(bundle.Migration)
			if err != nil {
				return err
			}
			migration, err := release.VerifySequenceMigrationHistorical(migrationEnvelope, roots, scope.Role, scope.Environment)
			if err != nil {
				return err
			}
			client, err := env.storage(migration.Region)
			if err != nil {
				return err
			}
			allocations := release.SequenceLocation{Client: client, Namespace: migration.Namespace, Bucket: migration.Bucket}
			verified, err := release.VerifyContainerCurrent(c.ctx, bundle, roots, scope, now, deadline, containerEvidenceReader(filepath.Join(*directory, "production")), allocations)
			if err != nil {
				return err
			}
			claim = verified.Claim()
			if role == "" {
				source, repository, tree, role, environment, sequence = claim.SourceRevision, claim.SourceRepository, claim.SourceTreeSHA256, claim.Role, claim.Environment, claim.ReleaseSequence
			}
			if source != claim.SourceRevision || repository != claim.SourceRepository || tree != claim.SourceTreeSHA256 || role != claim.Role || environment != claim.Environment || sequence != claim.ReleaseSequence {
				return errors.New("container bundle mixes source identities, roles, environments or sequences")
			}
			repositoryImage, _, ok := strings.Cut(claim.Image, "@sha256:")
			if !ok {
				return errors.New("container image has no immutable digest")
			}
			inspected, err := release.InspectContainerImageLayout(c.ctx, filepath.Join(*directory, "oci-layout"), repositoryImage+"@sha256:"+claim.QualificationSHA256, claim.Architecture)
			if err != nil {
				return err
			}
			if inspected.Image != claim.Image {
				return errors.New("retained OCI layout root differs from signed child image")
			}
			if len(targets[scope.Cell]) == 0 {
				cells = append(cells, scope.Cell)
			}
			targets[scope.Cell] = append(targets[scope.Cell], target{bundle: bundle, verified: verified, scope: scope, allocations: allocations})
		}
	}
	if len(targets) == 0 {
		return errors.New("container bundle contains no regions or architectures")
	}
	progress := &deploymentWriter{Writer: c.output}
	failures := make([]error, len(cells))
	var group errgroup.Group
	group.SetLimit(4)
	for index, cell := range cells {
		group.Go(func() error {
			ctx, cancel := context.WithTimeout(c.ctx, budget)
			defer cancel()
			regional := c
			regional.ctx = ctx
			apply := func() error {
				deadline := time.Now().UTC().Add(budget)
				location, err := channelLocation(env, cell, *namespace)
				if err != nil {
					return err
				}
				alternatives := make([]release.VerifiedContainer, 0, len(targets[cell]))
				// Qualified architectures are alternatives for one regional service.
				// Trusted runtime placement selects one; status cannot admit a platform.
				for _, target := range targets[cell] {
					claim := target.verified.Claim()
					if err := regional.uploadContainerEvidence(*directory, location, target.verified, roots, deadline); err != nil {
						return err
					}
					if err := releasechannel.PublishContainer(ctx, location, target.bundle, roots, target.scope, time.Now().UTC(), deadline, func(ctx context.Context, digest string) (io.ReadCloser, error) {
						return releasechannel.ReadContainerEvidence(ctx, location, claim.Role, digest)
					}, target.allocations); err != nil {
						return err
					}
					fmt.Fprintf(progress, "%s %s %s published signed OCI %s\n", claim.Cell, claim.Role, claim.Architecture, claim.Image)
					alternatives = append(alternatives, target.verified)
				}
				return awaitContainer(ctx, location, alternatives, deadline, progress)
			}
			if err := apply(); err != nil {
				failures[index] = fmt.Errorf("%s %s: %w", cell, role, err)
				fmt.Fprintf(progress, "%s %s failed: %v\n", cell, role, err)
			}
			return nil
		})
	}
	_ = group.Wait()
	return errors.Join(failures...)
}

func (c command) uploadContainerEvidence(directory string, location releasechannel.Location, verified release.VerifiedContainer, roots trust.Keyring, deadline time.Time) error {
	claim := verified.Claim()
	_, digest, _ := strings.Cut(claim.Image, "@sha256:")
	expected := release.ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: digest, QualificationSHA256: claim.QualificationSHA256, Cell: claim.Cell, Environment: claim.Environment, Runtime: release.ProductionRuntime, Architecture: claim.Architecture, Role: claim.Role}
	proof, err := release.VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, expected, deadline)
	if err != nil {
		return err
	}
	type retained struct {
		path, digest string
		size         int64
	}
	objects := make([]retained, 0, len(proof.Evidence)+2)
	for _, evidence := range proof.Evidence {
		objects = append(objects, retained{filepath.Join(directory, "production", "objects", evidence.SHA256), evidence.SHA256, evidence.Bytes})
	}
	// Retain the actual immutable root/index and child bytes alongside the signed
	// runtime gates; they remain standard OCI blobs with their original digests.
	for _, metadata := range []string{claim.QualificationSHA256, digest} {
		objects = append(objects, retained{filepath.Join(directory, "oci-layout", "blobs", "sha256", metadata), metadata, 0})
	}
	for _, object := range objects {
		file, size, sum, err := c.openHashedArtifact(object.path, release.MaxProductionEvidenceBytes)
		if errors.Is(err, os.ErrNotExist) && object.digest == claim.QualificationSHA256 {
			file, size, sum, err = c.openHashedArtifact(filepath.Join(directory, "oci-layout", "index.json"), release.MaxProductionEvidenceBytes)
		}
		if err != nil {
			return err
		}
		if hex.EncodeToString(sum) != object.digest || object.size != 0 && size != object.size {
			file.Close()
			return errors.New("retained OCI qualification bytes changed")
		}
		if !verified.Valid(time.Now().UTC()) {
			file.Close()
			return trust.ErrExpired
		}
		putErr := putImmutable(c.ctx, location.Client, location.Namespace, location.Bucket, releasechannel.ContainerEvidenceObject(claim.Role, object.digest), file, size, sum)
		if err := errors.Join(putErr, file.Close()); err != nil {
			return err
		}
	}
	return nil
}

func awaitContainer(ctx context.Context, location releasechannel.Location, alternatives []release.VerifiedContainer, deadline time.Time, output io.Writer) error {
	for {
		var failures []error
		for _, verified := range alternatives {
			claim := verified.Claim()
			status, found, err := releasechannel.ReadContainerStatus(ctx, location, claim.Role, claim.Architecture)
			if err != nil {
				return err
			}
			if !found || status.Schema != releasechannel.ContainerStatusSchema || status.Cell != claim.Cell || status.Environment != claim.Environment || status.Role != claim.Role || status.Architecture != claim.Architecture || status.Image != claim.Image || status.ReleaseSequence != claim.ReleaseSequence || status.Fingerprint != verified.Fingerprint() {
				continue
			}
			switch status.State {
			case releasechannel.StateComplete:
				if !verified.Valid(time.Now().UTC()) {
					return trust.ErrExpired
				}
				fmt.Fprintf(output, "%s %s %s complete: %s\n", claim.Cell, claim.Role, claim.Architecture, claim.Image)
				return nil
			case releasechannel.StateFailed:
				failures = append(failures, fmt.Errorf("%s: %w: %s", claim.Architecture, releasechannel.ErrFailed, status.Reason))
			}
		}
		if len(failures) == len(alternatives) {
			return errors.Join(failures...)
		}
		if !time.Now().Before(deadline) {
			return fmt.Errorf("%w: container did not become ready before deadline", releasechannel.ErrFailed)
		}
		timer := time.NewTimer(min(5*time.Second, time.Until(deadline)))
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
}

func PublishContainer(ctx context.Context, location Location, bundle release.ContainerBundle, roots trust.Keyring, target release.ContainerTarget, now, deadline time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations release.SequenceLocation) error {
	verified, err := release.VerifyContainerCurrent(ctx, bundle, roots, target, now, deadline, evidence, allocations)
	if err != nil {
		return err
	}
	incoming := verified.Claim()
	bucket, err := BucketName(target.Cell)
	if err != nil {
		return err
	}
	if location.Bucket != bucket || location.Namespace != verified.Migration().Namespace {
		return fmt.Errorf("%w: container publication target", ErrInvalid)
	}
	wire, err := json.Marshal(bundle, json.Deterministic(true))
	if err != nil {
		return err
	}
	if len(wire) > MaxContainerBundleBytes {
		return fmt.Errorf("%w: container bundle exceeds bound", ErrInvalid)
	}
	name := ContainerReleaseObject(target.Role, target.Architecture)
	for range 3 {
		current, etag, found, err := location.get(ctx, name, MaxContainerBundleBytes)
		if err != nil {
			return err
		}
		if found {
			var retained release.ContainerBundle
			if err := protocol.DecodeStrict(current, &retained, MaxContainerBundleBytes); err != nil {
				return err
			}
			previous, err := release.VerifyContainerHistorical(retained, roots, target)
			if err != nil {
				return fmt.Errorf("authenticate retained container floor: %w", err)
			}
			floor := previous.Claim()
			if incoming.ReleaseSequence < floor.ReleaseSequence {
				return ErrStale
			}
			if incoming.ReleaseSequence == floor.ReleaseSequence && verified.ReleaseIdentity() != previous.ReleaseIdentity() {
				return fmt.Errorf("%w: container sequence already names different content", ErrInvalid)
			}
		} else {
			if _, err := release.VerifySequenceMigrationCurrent(verified.MigrationEnvelope(), roots, target.Role, target.Environment, now); err != nil {
				return err
			}
		}
		if !verified.Valid(time.Now().UTC()) {
			return trust.ErrExpired
		}
		if err := location.put(ctx, name, wire, etag); !errors.Is(err, ErrConflict) {
			return err
		}
	}
	return ErrConflict
}

func VerifyContainerCurrent(ctx context.Context, bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget, now, validUntil time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations SequenceLocation) (VerifiedContainer, error) {
	if now.IsZero() || validUntil.Before(now) || !ValidRegion(expected.Cell) || !ValidEnvironment(expected.Environment) || !serviceRolePattern.MatchString(expected.Role) || expected.Architecture != "arm64" && expected.Architecture != "amd64" || evidence == nil {
		return VerifiedContainer{}, errors.New("container verification requires admitted target, current time, deadline and evidence store")
	}
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return VerifiedContainer{}, err
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	verify := func(at time.Time) ([]byte, error) {
		if len(bundle.Delegation) == 0 {
			return trust.VerifyCurrent(envelope, ContainerScope(expected), roots, at, policy)
		}
		grant, err := trust.DecodeEnvelope(bundle.Delegation)
		if err != nil {
			return nil, err
		}
		delegation, err := trust.VerifyDelegationCurrent(grant, roots, at, policy)
		if err != nil {
			return nil, err
		}
		return trust.VerifyDelegatedCurrent(envelope, ContainerScope(expected), delegation, at, policy)
	}
	payload, err := verify(now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := verify(validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	verified, err := verifyContainerIdentity(bundle, roots, expected, envelope, payload)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.familyEvidence, err = allocations.readWorkerFamily(ctx, roots, verified)
	if err != nil {
		return VerifiedContainer{}, err
	}
	claim := verified.claim
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	candidate := ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment, Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: expected.Role}
	proof, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	for _, retained := range proof.Evidence {
		reader, err := evidence(ctx, retained.SHA256)
		if err != nil {
			return VerifiedContainer{}, fmt.Errorf("read qualification evidence: %w", err)
		}
		if reader == nil {
			return VerifiedContainer{}, errors.New("qualification evidence store returned no reader")
		}
		hash := sha256.New()
		n, readErr := io.Copy(hash, io.LimitReader(reader, retained.Bytes+1))
		closeErr := reader.Close()
		if err := errors.Join(readErr, closeErr); err != nil {
			return VerifiedContainer{}, err
		}
		if n != retained.Bytes || fmt.Sprintf("%x", hash.Sum(nil)) != retained.SHA256 {
			return VerifiedContainer{}, errors.New("container qualification evidence bytes differ from signed proof")
		}
	}
	qualificationEnvelope, err := trust.DecodeEnvelope(claim.Production.Qualification)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.issuedAt = envelope.IssuedAt
	if qualificationEnvelope.IssuedAt.After(verified.issuedAt) {
		verified.issuedAt = qualificationEnvelope.IssuedAt
	}
	verified.expiresAt = validUntil
	for _, expires := range []time.Time{envelope.ExpiresAt, qualificationEnvelope.ExpiresAt} {
		if expires.Before(verified.expiresAt) {
			verified.expiresAt = expires
		}
	}
	return verified, nil
}

// HistoricalContainer authenticates retained ordering evidence without granting runtime authority.
type HistoricalContainer struct{ value VerifiedContainer }

func (c HistoricalContainer) Claim() ContainerClaim   { return c.value.Claim() }
func (c HistoricalContainer) Fingerprint() string     { return c.value.Fingerprint() }
func (c HistoricalContainer) ReleaseIdentity() string { return c.value.ReleaseIdentity() }

// VerifyContainerHistorical authenticates an immutable channel floor, including expired
// release/delegation intervals. Runtime consumers must use VerifyContainerCurrent.
func VerifyContainerHistorical(bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget) (HistoricalContainer, error) {
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return HistoricalContainer{}, err
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(bundle.Delegation) == 0 {
		payload, err = trust.VerifyHistorical(envelope, ContainerScope(expected), roots, policy)
	} else {
		grant, decodeErr := trust.DecodeEnvelope(bundle.Delegation)
		if decodeErr != nil {
			return HistoricalContainer{}, decodeErr
		}
		delegation, verifyErr := trust.VerifyDelegationHistorical(grant, roots, policy)
		if verifyErr != nil {
			return HistoricalContainer{}, verifyErr
		}
		payload, err = trust.VerifyDelegatedHistorical(envelope, ContainerScope(expected), delegation, policy)
	}
	if err != nil {
		return HistoricalContainer{}, err
	}
	verified, err := verifyContainerIdentity(bundle, roots, expected, envelope, payload)
	if err != nil {
		return HistoricalContainer{}, err
	}
	return HistoricalContainer{value: verified}, nil
}

func verifyContainerIdentity(bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget, envelope trust.Envelope, payload []byte) (VerifiedContainer, error) {
	if !ValidRegion(expected.Cell) || !ValidEnvironment(expected.Environment) || !serviceRolePattern.MatchString(expected.Role) || expected.Architecture != "arm64" && expected.Architecture != "amd64" {
		return VerifiedContainer{}, errors.New("container verification requires admitted target")
	}
	var claim ContainerClaim
	if err := protocol.DecodeStrict(payload, &claim, trust.MaxPayloadBytes); err != nil {
		return VerifiedContainer{}, err
	}
	if err := claim.Validate(); err != nil {
		return VerifiedContainer{}, err
	}
	if err := verifyContainerIndex(bundle.Index, claim); err != nil {
		return VerifiedContainer{}, err
	}
	if claim.Cell != expected.Cell || claim.Environment != expected.Environment || claim.Role != expected.Role || claim.Architecture != expected.Architecture {
		return VerifiedContainer{}, trust.ErrScopeMismatch
	}
	migrationEnvelope, err := trust.DecodeEnvelope(bundle.Migration)
	if err != nil {
		return VerifiedContainer{}, err
	}
	migration, err := VerifySequenceMigrationHistorical(migrationEnvelope, roots, expected.Role, expected.Environment)
	if err != nil {
		return VerifiedContainer{}, err
	}
	migrationDigest, err := trust.Fingerprint(migrationEnvelope)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if claim.ReleaseSequence <= migration.SequenceFloor || claim.SequenceMigrationSHA256 != migrationDigest || envelope.KeyID != migration.SignerKeyID {
		return VerifiedContainer{}, errors.New("container release differs from root-authorized sequence signer or migration")
	}
	if err := verifyWorkerFamilyEvidence(bundle.Sequence, roots, claim); err != nil {
		return VerifiedContainer{}, err
	}
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return VerifiedContainer{}, err
	}
	content, err := claim.ContentManifestDigest()
	if err != nil {
		return VerifiedContainer{}, err
	}
	bundleDigest, err := ContainerBundleSHA256(bundle)
	if err != nil {
		return VerifiedContainer{}, err
	}
	identity := fmt.Sprintf("%x", sha256.Sum256([]byte(content+"/"+claim.SequenceMigrationSHA256)))
	return VerifiedContainer{claim: claim, bundleSHA256: bundleDigest, familyEvidence: slices.Clone(bundle.Sequence), migration: migration, migrationEnvelope: migrationEnvelope, fingerprint: fingerprint, identity: identity}, nil
}

func verifyWorkerFamilyEvidence(wire []byte, roots trust.Keyring, claim ContainerClaim) error {
	if len(wire) == 0 || len(wire) > MaxWorkerFamilyEvidenceBytes {
		return errors.New("worker family evidence exceeds bound or is missing")
	}
	head, err := verifySequenceHead(wire, roots, claim.Role, claim.Environment)
	if err != nil {
		return err
	}
	migration, err := trust.Fingerprint(head.Migration)
	if err != nil {
		return err
	}
	family, err := claim.WorkerFamilyDigest()
	if err != nil {
		return err
	}
	expected := SequenceIdentity{Role: claim.Role, Environment: claim.Environment, SourceRevision: claim.SourceRevision, ManifestSHA256: family}
	if head.Sequence != claim.ReleaseSequence || head.Identity != expected || migration != claim.SequenceMigrationSHA256 {
		return errors.New("worker differs from authenticated sequence family")
	}
	return nil
}

// readWorkerFamily reads the immutable global winner, never the advancing head.
func (location SequenceLocation) readWorkerFamily(ctx context.Context, roots trust.Keyring, verified VerifiedContainer) ([]byte, error) {
	migration := verified.migration
	if location.Client == nil || location.Namespace != migration.Namespace || location.Bucket != migration.Bucket {
		return nil, errors.New("worker family reader differs from root-authorized sequence location")
	}
	claim := verified.claim
	name := SequenceReservationObject(claim.Role, claim.Environment, claim.SequenceMigrationSHA256, claim.ReleaseSequence)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if err != nil {
		return nil, err
	}
	if response.Content == nil {
		return nil, errors.New("worker family allocation has no body")
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, MaxWorkerFamilyEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if err := verifyWorkerFamilyEvidence(wire, roots, claim); err != nil {
		return nil, err
	}
	return wire, nil
}

func verifyContainerIndex(wire []byte, claim ContainerClaim) error {
	_, child, _ := strings.Cut(claim.Image, "@sha256:")
	if claim.QualificationSHA256 == child && len(wire) == 0 {
		return nil
	}
	if len(wire) == 0 || len(wire) > MaxContainerIndexBytes || fmt.Sprintf("%x", sha256.Sum256(wire)) != claim.QualificationSHA256 {
		return errors.New("container qualification requires exact bounded retained OCI index bytes")
	}
	var index ocispec.Index
	if err := json.Unmarshal(wire, &index); err != nil || index.SchemaVersion != 2 || index.MediaType != "" && index.MediaType != ocispec.MediaTypeImageIndex && index.MediaType != "application/vnd.docker.distribution.manifest.list.v2+json" || index.ArtifactType != "" || index.Subject != nil || len(index.Manifests) == 0 || len(index.Manifests) > 512 {
		return errors.New("container qualification root is not a standard OCI platform index")
	}
	matches := 0
	for _, descriptor := range index.Manifests {
		platform := descriptor.Platform
		if platform == nil || platform.OS != "linux" || platform.Architecture != claim.Architecture {
			continue
		}
		matches++
		if descriptor.Digest.String() != "sha256:"+child || descriptor.Digest.Validate() != nil || descriptor.Size <= 0 || descriptor.Size > 8<<20 || descriptor.MediaType != ocispec.MediaTypeImageManifest && descriptor.MediaType != "application/vnd.docker.distribution.manifest.v2+json" || len(descriptor.URLs) != 0 || len(descriptor.Data) != 0 || descriptor.ArtifactType != "" || platform.Variant != "" && !(claim.Architecture == "arm64" && platform.Variant == "v8") || platform.OSVersion != "" || len(platform.OSFeatures) != 0 {
			return errors.New("retained OCI index does not bind the exact native child image")
		}
	}
	if matches != 1 {
		return errors.New("retained OCI index requires one matching Linux architecture child")
	}
	return nil
}

func SourceTreeDigest(ctx context.Context, checkout, commit string) (string, error) {
	if !ValidSourceRevision(commit) {
		return "", errors.New("--commit must be a full lowercase commit SHA")
	}
	// Archive from an empty repository that borrows the checkout's objects,
	// so no attributes from outside the commit (info/attributes,
	// core.attributesFile, the system file) apply, and pin the file modes.
	// No inherited GIT_* variable reaches git.
	env := []string{"GIT_ATTR_NOSYSTEM=1"}
	for _, variable := range os.Environ() {
		if !strings.HasPrefix(variable, "GIT_") {
			env = append(env, variable)
		}
	}
	git := func(args ...string) *exec.Cmd {
		command := exec.CommandContext(ctx, "git", args...)
		command.Env = env
		return command
	}
	objects, err := git("-C", checkout, "rev-parse", "--path-format=absolute", "--git-path", "objects").Output()
	if err != nil {
		return "", fmt.Errorf("find the objects of %s: %w", checkout, err)
	}
	isolated, err := os.MkdirTemp("", "ts-source-tree-")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(isolated)
	// The empty repository and its archive read no system or global
	// config (an init.templateDir could bring info/attributes) and no
	// template; reading the checkout may still need the user's safe.directory.
	isolate := func(command *exec.Cmd) *exec.Cmd {
		command.Env = append(command.Env, "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_GLOBAL=/dev/null")
		return command
	}
	if out, err := isolate(git("init", "-q", "--bare", "--template=", isolated)).CombinedOutput(); err != nil {
		return "", fmt.Errorf("prepare the source archive: %w: %s", err, out)
	}
	command := isolate(git("--git-dir", isolated, "-c", "tar.umask=0002", "-c", "core.attributesFile=/dev/null",
		"archive", "--format=tar", commit+"^{commit}"))
	command.Env = append(command.Env, "GIT_ALTERNATE_OBJECT_DIRECTORIES="+strings.TrimSpace(string(objects)))
	stdout, err := command.StdoutPipe()
	if err != nil {
		return "", err
	}
	if err := command.Start(); err != nil {
		return "", err
	}
	hash := sha256.New()
	_, copyErr := io.Copy(hash, stdout)
	if err := errors.Join(copyErr, command.Wait()); err != nil {
		return "", fmt.Errorf("archive source %s: %w", commit, err)
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func InspectContainerImageLayout(ctx context.Context, directory, pinnedImage, architecture string) (ContainerImage, error) {
	if architecture != "arm64" && architecture != "amd64" {
		return ContainerImage{}, errors.New("container image architecture must be arm64 or amd64")
	}
	ref, err := reference.ParseNormalizedNamed(pinnedImage)
	if err != nil {
		return ContainerImage{}, errors.New("container image requires a canonical digest reference")
	}
	canonical, ok := ref.(reference.Canonical)
	_, tagged := ref.(reference.Tagged)
	if !ok || tagged || canonical.String() != pinnedImage || canonical.Digest().Validate() != nil || canonical.Digest().Algorithm().String() != "sha256" {
		return ContainerImage{}, errors.New("container image requires a canonical sha256 reference without a tag")
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return ContainerImage{}, fmt.Errorf("open OCI image layout: %w", err)
	}
	defer root.Close()
	layout := containerLayout{root: root, ctx: ctx}
	wire, err := layout.read("oci-layout", maxContainerMetadataBytes)
	if err != nil {
		return ContainerImage{}, err
	}
	var version ocispec.ImageLayout
	if err := json.Unmarshal(wire, &version); err != nil || version.Version != ocispec.ImageLayoutVersion {
		return ContainerImage{}, errors.New("unsupported OCI image layout version")
	}
	wire, err = layout.read("index.json", maxContainerMetadataBytes)
	if err != nil {
		return ContainerImage{}, err
	}
	var index ocispec.Index
	if err := json.Unmarshal(wire, &index); err != nil || index.SchemaVersion != 2 || index.MediaType != "" && index.MediaType != ocispec.MediaTypeImageIndex || len(index.Manifests) == 0 || len(index.Manifests) > maxContainerLayers {
		return ContainerImage{}, errors.New("invalid OCI image layout index")
	}
	var descriptor ocispec.Descriptor
	rootIsIndex := fmt.Sprintf("%x", sha256.Sum256(wire)) == canonical.Digest().Encoded()
	if rootIsIndex {
		descriptor = ocispec.Descriptor{MediaType: ocispec.MediaTypeImageIndex, Digest: canonical.Digest(), Size: int64(len(wire))}
	} else {
		for _, candidate := range index.Manifests {
			if candidate.Digest == canonical.Digest() {
				if descriptor.Digest != "" {
					return ContainerImage{}, errors.New("OCI layout repeats the pinned image")
				}
				descriptor = candidate
			}
		}
	}
	if descriptor.Digest == "" {
		return ContainerImage{}, errors.New("pinned image is absent from OCI layout index")
	}
	result := ContainerImage{Architecture: architecture}
	if descriptor.MediaType == ocispec.MediaTypeImageIndex || descriptor.MediaType == "application/vnd.docker.distribution.manifest.list.v2+json" {
		if !rootIsIndex {
			wire, err = layout.blob(descriptor, maxContainerMetadataBytes, true)
			if err != nil {
				return ContainerImage{}, err
			}
		}
		var platforms ocispec.Index
		if err := json.Unmarshal(wire, &platforms); err != nil || platforms.SchemaVersion != 2 || platforms.MediaType != "" && platforms.MediaType != descriptor.MediaType || len(platforms.Manifests) == 0 || len(platforms.Manifests) > maxContainerLayers || platforms.ArtifactType != "" || platforms.Subject != nil {
			return ContainerImage{}, errors.New("invalid pinned OCI platform index")
		}
		result.IndexSHA256 = descriptor.Digest.Encoded()
		descriptor = ocispec.Descriptor{}
		for _, child := range platforms.Manifests {
			if child.Platform != nil && child.Platform.OS == "linux" && child.Platform.Architecture == architecture {
				if descriptor.Digest != "" {
					return ContainerImage{}, errors.New("OCI index has multiple matching platform children")
				}
				descriptor = child
			}
		}
		if descriptor.Digest == "" {
			return ContainerImage{}, errors.New("OCI index lacks the required Linux architecture")
		}
	}
	if descriptor.MediaType != ocispec.MediaTypeImageManifest && descriptor.MediaType != "application/vnd.docker.distribution.manifest.v2+json" {
		return ContainerImage{}, errors.New("container child must be an OCI or Docker v2 image manifest")
	}
	if p := descriptor.Platform; p != nil && (p.OS != "linux" || p.Architecture != architecture || p.Variant != "" && !(architecture == "arm64" && p.Variant == "v8") || p.OSVersion != "" || len(p.OSFeatures) != 0) {
		return ContainerImage{}, errors.New("container platform requires unsupported OS or CPU features")
	}
	wire, err = layout.blob(descriptor, maxContainerMetadataBytes, true)
	if err != nil {
		return ContainerImage{}, err
	}
	var manifest ocispec.Manifest
	if err := json.Unmarshal(wire, &manifest); err != nil || manifest.SchemaVersion != 2 || manifest.MediaType != "" && manifest.MediaType != descriptor.MediaType || manifest.ArtifactType != "" || manifest.Subject != nil || len(manifest.Layers) > maxContainerLayers {
		return ContainerImage{}, errors.New("invalid OCI container child manifest")
	}
	if manifest.Config.MediaType != ocispec.MediaTypeImageConfig && manifest.Config.MediaType != "application/vnd.docker.container.image.v1+json" {
		return ContainerImage{}, errors.New("container manifest has an unsupported image config")
	}
	wire, err = layout.blob(manifest.Config, maxContainerMetadataBytes, true)
	if err != nil {
		return ContainerImage{}, err
	}
	var config ocispec.Image
	if err := json.Unmarshal(wire, &config); err != nil || config.OS != "linux" || config.Architecture != architecture || config.Variant != "" && !(architecture == "arm64" && config.Variant == "v8") || config.OSVersion != "" || len(config.OSFeatures) != 0 || config.RootFS.Type != "layers" || len(config.RootFS.DiffIDs) != len(manifest.Layers) {
		return ContainerImage{}, errors.New("container config differs from the required Linux architecture or layers")
	}
	// shortcut: containerd checks uncompressed DiffIDs; add unpack checks if producer qualification must prove them.
	for index, layer := range manifest.Layers {
		switch layer.MediaType {
		case ocispec.MediaTypeImageLayer, ocispec.MediaTypeImageLayerGzip, ocispec.MediaTypeImageLayerZstd, "application/vnd.docker.image.rootfs.diff.tar.gzip":
		default:
			return ContainerImage{}, errors.New("container manifest has an unsupported layer media type")
		}
		if diff := config.RootFS.DiffIDs[index]; diff.Validate() != nil || diff.Algorithm().String() != "sha256" {
			return ContainerImage{}, errors.New("container config contains an invalid layer diff digest")
		}
		if _, err := layout.blob(layer, maxContainerLayerBytes, false); err != nil {
			return ContainerImage{}, err
		}
	}
	result.ManifestSHA256 = descriptor.Digest.Encoded()
	result.Image = reference.TrimNamed(ref).String() + "@" + descriptor.Digest.String()
	return result, ctx.Err()
}

type containerLayout struct {
	root  *os.Root
	ctx   context.Context
	bytes int64
}

func (layout *containerLayout) read(name string, limit int64) ([]byte, error) {
	file, err := layout.open(name, limit)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	var wire bytes.Buffer
	if _, err := layout.copy(&wire, file, limit); err != nil {
		return nil, err
	}
	return wire.Bytes(), nil
}

func (layout *containerLayout) open(name string, limit int64) (*os.File, error) {
	if err := layout.ctx.Err(); err != nil {
		return nil, err
	}
	// Nonblocking open rejects a FIFO without waiting for an untrusted writer.
	file, err := layout.root.OpenFile(name, os.O_RDONLY|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, fmt.Errorf("read retained OCI layout file: %w", err)
	}
	stat, err := file.Stat()
	if err != nil || !stat.Mode().IsRegular() || stat.Size() < 0 || stat.Size() > limit {
		file.Close()
		return nil, errors.New("OCI layout file must be a bounded regular file")
	}
	return file, nil
}

func (layout *containerLayout) copy(dst io.Writer, src io.Reader, limit int64) (int64, error) {
	buffer := make([]byte, 128<<10)
	var total int64
	for total <= limit {
		if err := layout.ctx.Err(); err != nil {
			return total, err
		}
		n, err := src.Read(buffer[:min(int64(len(buffer)), limit-total+1)])
		total += int64(n)
		layout.bytes += int64(n)
		if total > limit || layout.bytes > maxContainerLayoutBytes {
			return total, errors.New("retained OCI image exceeds byte limit")
		}
		if _, writeErr := dst.Write(buffer[:n]); writeErr != nil {
			return total, writeErr
		}
		if errors.Is(err, io.EOF) {
			return total, nil
		}
		if err != nil {
			return total, err
		}
	}
	return total, errors.New("retained OCI image exceeds byte limit")
}

func (layout *containerLayout) blob(descriptor ocispec.Descriptor, limit int64, retain bool) ([]byte, error) {
	if descriptor.Digest.Validate() != nil || descriptor.Digest.Algorithm().String() != "sha256" || descriptor.Size <= 0 || descriptor.Size > limit || len(descriptor.URLs) != 0 || len(descriptor.Data) != 0 || descriptor.ArtifactType != "" {
		return nil, errors.New("OCI descriptor requires a bounded local sha256 blob")
	}
	file, err := layout.open("blobs/sha256/"+descriptor.Digest.Encoded(), limit)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	hash := sha256.New()
	var wire bytes.Buffer
	var dst io.Writer = hash
	if retain {
		dst = io.MultiWriter(hash, &wire)
	}
	n, err := layout.copy(dst, file, descriptor.Size)
	if err != nil {
		return nil, err
	}
	if n != descriptor.Size || fmt.Sprintf("%x", hash.Sum(nil)) != descriptor.Digest.Encoded() {
		return nil, errors.New("retained OCI blob differs from its descriptor digest or size")
	}
	return wire.Bytes(), nil
}

func (location SequenceLocation) AllocateWithEvidence(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (uint64, []byte, error) {
	head, err := location.allocate(ctx, identity, roots, signer)
	if err != nil {
		return 0, nil, err
	}
	wire, err := location.retainReservation(ctx, head, roots)
	if err != nil {
		return 0, nil, err
	}
	return head.Sequence, wire, nil
}

func (location SequenceLocation) allocate(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (sequenceHead, error) {
	if err := identity.validate(); err != nil {
		return sequenceHead{}, err
	}
	for range 32 {
		head, etag, found, err := location.read(ctx, identity.Role, identity.Environment, roots)
		if err != nil {
			return sequenceHead{}, err
		}
		if !found {
			return sequenceHead{}, ErrSequenceMigrationRequired
		}
		migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, identity.Role, identity.Environment)
		if err != nil {
			return sequenceHead{}, err
		}
		if len(signer) != ed25519.PrivateKeySize {
			return sequenceHead{}, trust.ErrKeyMismatch
		}
		signerID, err := trust.KeyID(signer.Public().(ed25519.PublicKey))
		if err != nil || signerID != migration.SignerKeyID {
			return sequenceHead{}, trust.ErrKeyMismatch
		}
		if head.Identity == identity {
			return head, nil
		}
		if head.Sequence == math.MaxUint64 {
			return sequenceHead{}, fmt.Errorf("%w: sequence exhausted", ErrInvalidReceipt)
		}
		head.Sequence++
		head.Identity = identity
		payload, err := trust.EncodePayload(sequenceReservation{Sequence: head.Sequence, Identity: identity})
		if err != nil {
			return sequenceHead{}, err
		}
		now := time.Now().UTC()
		head.Reservation, err = trust.Sign(payload, sequenceReservationScope(identity.Role, identity.Environment), now, now.Add(MaxReceiptLifetime), signer)
		if err != nil {
			return sequenceHead{}, err
		}
		if err := location.write(ctx, identity.Role, identity.Environment, head, etag); errors.Is(err, ErrSequenceConflict) {
			continue
		} else if err != nil {
			return sequenceHead{}, err
		}
		return head, nil
	}
	return sequenceHead{}, ErrSequenceConflict
}

// ImportMigration creates the ordering namespace once. A different migration
// never overwrites an allocated sequence or an earlier migration.
func (location SequenceLocation) ImportMigration(ctx context.Context, envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) error {
	migration, err := VerifySequenceMigrationHistorical(envelope, roots, role, environment)
	if err != nil {
		return err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket {
		return fmt.Errorf("%w: migration sequence location", ErrInvalidReceipt)
	}
	head, etag, found, err := location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		existing, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if existing == incoming {
			return nil
		}
		return fmt.Errorf("%w: namespace already migrated", ErrSequenceConflict)
	}
	if _, err := VerifySequenceMigrationCurrent(envelope, roots, role, environment, now); err != nil {
		return err
	}
	err = location.write(ctx, role, environment, sequenceHead{Schema: "terrascale.release.sequence.v1", Sequence: migration.SequenceFloor, Migration: envelope}, etag)
	if !errors.Is(err, ErrSequenceConflict) {
		return err
	}
	// Another producer may initialize the exact same grant concurrently.
	head, _, found, err = location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		retained, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if retained == incoming {
			return nil
		}
	}
	return ErrSequenceConflict
}

func (location SequenceLocation) read(ctx context.Context, role, environment string, roots trust.Keyring) (sequenceHead, string, bool, error) {
	var head sequenceHead
	if location.Client == nil || location.Namespace == "" || location.Bucket == "" {
		return head, "", false, fmt.Errorf("%w: sequence location", ErrInvalidReceipt)
	}
	name := SequenceObject(role, environment)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if sequenceHTTPStatus(err) == http.StatusNotFound {
		return head, "", false, nil
	}
	if err != nil {
		return head, "", false, err
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, trust.MaxEnvelopeBytes+1))
	if err != nil {
		return head, "", false, err
	}
	head, err = verifySequenceHead(wire, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket || response.ETag == nil || *response.ETag == "" {
		return head, "", false, fmt.Errorf("%w: migration sequence location or ETag", ErrInvalidReceipt)
	}
	return head, *response.ETag, true, nil
}

func (location SequenceLocation) write(ctx context.Context, role, environment string, head sequenceHead, etag string) error {
	wire, err := json.Marshal(head, json.Deterministic(true))
	if err != nil {
		return err
	}
	name := SequenceObject(role, environment)
	request := objectstorage.PutObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name, ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)), ContentType: new("application/json")}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err = location.Client.PutObject(ctx, request)
	if sequenceHTTPStatus(err) == http.StatusPreconditionFailed {
		return ErrSequenceConflict
	}
	return err
}

